// Üretilen dosya: tool/ozgun/uret.py. Biyoloji · Hücre organelleri ve zar taşıma ayrıntılı (orta).
const ozBiology6Orta = <(String, String, List<String>, String)>[
  ('Aşağıdaki gözlemlerden hangisi hücre kuramının "hücreler yalnız var olan hücrelerden oluşur" önermesiyle doğrudan çelişirdi?', 'Cansız besiyerinde kendiliğinden hücre oluşması', ['Bir bakterinin ikiye bölünerek çoğalması', 'Döllenmiş yumurtanın bölünerek embriyo oluşturması', 'Bir deri yarasının kenardaki hücrelerin bölünmesiyle zamanla kapanması'], 'Önerme, hücrelerin kendiliğinden oluşmayıp önceki hücrelerden türediğini söyler; cansız maddeden hücre oluşması bu ilkeyi çürütürdü. Diğer seçenekler önermeyi destekleyen örneklerdir.'),
  ('Hücre zarının yapısını 1972\'de "akıcı mozaik model" ile açıklayan bilim insanları hangileridir?', 'Singer ve Nicolson', ['Watson ve Crick', 'Gorter ve Grendel', 'Schleiden ve Schwann'], 'S. J. Singer ve G. Nicolson, zarı proteinlerin yüzdüğü akışkan bir fosfolipit çift katmanı olarak tanımlamıştır.'),
  ('Zarı iki protein tabakası arasına sıkışmış bir lipit çift katmanı olarak tanımlayan 1935 tarihli "sandviç modeli"nin terk edilmesinde hangi bulgu belirleyici olmuştur?', 'Proteinlerin çift katmanın içine gömülü bulunması', ['Zarda hiç lipit bulunmaması', 'Zarın elektron mikroskobunda hiç görülememesi', 'Bütün hücre zarlarının birbirinin aynısı olan protein bileşimine sahip olması'], 'Davson-Danielli modeli proteinleri yalnız zarın yüzeylerine yerleştiriyordu. Dondurarak kırma gibi yöntemler proteinlerin çift katmanın içine gömüldüğünü göstererek akıcı mozaik modele geçişi sağladı.'),
  ('Hücre parçalarını santrifüjle ayırma çalışmaları sırasında lizozomları ve daha sonra peroksizomları keşfeden Belçikalı biyokimyacı kimdir?', 'Christian de Duve', ['George Palade', 'Robert Brown', 'Lynn Margulis'], 'Christian de Duve 1950\'lerde enzim ölçümleri yaparken lizozomları, ardından peroksizomları tanımlamıştır.'),
  ('Mayada otofajiyi denetleyen genleri bularak otofajinin mekanizmasını aydınlatması nedeniyle 2016 Nobel Fizyoloji veya Tıp Ödülü\'nü alan bilim insanı kimdir?', 'Yoshinori Ohsumi', ['Shinya Yamanaka', 'Randy Schekman', 'Tasuku Honjo'], 'Yoshinori Ohsumi 1990\'larda mayada otofaji genlerini tanımlamış ve 2016\'da tek başına Nobel Ödülü almıştır.'),
  ('Transmisyon elektron mikroskobuyla canlı bir hücrenin hareketlerini izlemek neden mümkün değildir?', 'Örnek vakumda, ölü ve kesitlenmiş olarak incelenir', ['Elektron demeti yalnız bitki hücrelerinin kalın çeperinden geçebildiği için', 'Büyütmesi ışık mikroskobundan düşüktür', 'Yalnız renkli örneklerin görüntüsünü verebilir'], 'Elektron demeti havadaki moleküllerle saçılacağı için mikroskobun içi vakumdur; örnekler sabitlenip kurutulur, kesitlenir ve ağır metallerle boyanır. Bu işlemler hücreyi öldürür.'),
  ('Boyanmamış canlı hücrelerdeki saydam yapıların kırılma indisi farklarını parlaklık farkına çevirerek görünür kılan mikroskop türü hangisidir?', 'Faz kontrast mikroskobu', ['Taramalı elektron mikroskobu', 'Transmisyon elektron mikroskobu', 'Basit büyüteç'], 'Faz kontrast mikroskobu, ışığın farklı yoğunluktaki yapılardan geçerken uğradığı faz kaymalarını kontrasta dönüştürür; böylece canlı ve boyasız hücreler incelenebilir.'),
  ('Konfokal (eş odaklı) mikroskobu sıradan floresan mikroskobundan üstün kılan özellik hangisidir?', 'Odak dışı ışığı eleyip net optik kesitler alması', ['Elektron demeti kullanarak tek tek atomları ve molekülleri görüntüleyebilmesi', 'Örneği boyamadan renkli göstermesi', 'Örneğin vakumda incelenmesini sağlaması'], 'Konfokal mikroskopta bir iğne deliği odak düzlemi dışından gelen ışığı engeller; farklı derinliklerden alınan net kesitler birleştirilerek üç boyutlu görüntü elde edilir.'),
  ('Floresanla işaretlenmiş zar proteinleri bulunan bir hücrenin küçük bir bölgesi güçlü lazer ışığıyla soldurulduktan sonra birkaç saniye içinde bu bölgenin yeniden parladığı görülüyor. Bu sonuç zar hakkında neyi gösterir?', 'Proteinlerin zar düzleminde yanal hareket ettiğini', ['Zar proteinlerinin sentezlendikleri yerde kalıp hiç yer değiştirmediğini', 'Lazerin yeni protein sentezini başlattığını', 'Zarın yalnız lipitlerden oluştuğunu'], 'Soldurulmuş bölgeye çevreden işaretli proteinlerin yanal difüzyonla gelmesi, zarın akışkan olduğunu gösterir. Bu yönteme FRAP denir.'),
  ('Kenarı 4 µm olan küp biçimli bir hücre, her birinin kenarı 2 µm olan 8 küçük küpe bölünürse toplam hacim değişmeden toplam yüzey alanı nasıl değişir?', 'İki katına çıkar', ['Değişmez', 'Dört katına çıkar', 'Yarıya iner'], 'Büyük küpün yüzeyi 6×16 = 96 µm², küçük küplerin toplam yüzeyi 8×6×4 = 192 µm² olur. Hacim 64 µm³ olarak kalır, yüzey ise iki katına çıkar.'),
  ('Hücre zarındaki doymamış yağ asidi zincirlerinin çift bağlarda bükülmesi zar üzerinde nasıl bir etki yapar?', 'Paketlenmeyi bozarak akışkanlığı artırır', ['Zarı her sıcaklıkta tamamen geçirimsiz ve katı bir tabakaya dönüştürür', 'Zarın kalınlığını iki katına çıkarır', 'Fosfolipitlerin su sevmeyen kuyruklarını su seven yapar'], 'Cis çift bağların oluşturduğu kıvrımlar, komşu zincirlerin birbirine yaklaşıp düzenli dizilmesini engeller; bu da zarın düşük sıcaklıkta bile akışkan kalmasını sağlar.'),
  ('Soğuk sulara aktarılan bir balığın hücre zarlarında birkaç hafta içinde doymamış yağ asidi oranının arttığı ölçülüyor. Bu değişikliğin uyumsal önemi nedir?', 'Soğukta zarın akışkan kalmasını sağlamak', ['Zarın su geçirgenliğini sıfıra indirmek', 'Hücrenin enerji harcamasını tamamen durdurup kış uykusuna hazırlanması', 'Zardaki proteinlerin sayısını azaltmak'], 'Sıcaklık düştükçe zar katılaşma eğilimi gösterir. Daha fazla doymamış yağ asidi kullanmak bu katılaşmayı engeller ve zar proteinlerinin çalışabilmesi için gereken akışkanlığı korur.'),
  ('Fosfolipitlerdeki yağ asidi zincirlerinin kısalması zarın akışkanlığını nasıl etkiler?', 'Zincirler arası etkileşim azaldığı için akışkanlık artar', ['Zincirler sıkı paketlendiği için akışkanlık azalır', 'Akışkanlık hiç değişmez', 'Zar tek katlı hâle gelir'], 'Kısa zincirler birbirleriyle daha az hidrofobik etkileşim kurar; bu yüzden zar daha akışkan olur. Uzun ve doymuş zincirler ise zarı daha katı yapar.'),
  ('Hayvan hücre zarlarında kolesterolün üstlendiği görevi mantar hücre zarlarında hangi sterol üstlenir?', 'Ergosterol', ['Kolesterol', 'Sitosterol', 'Testosteron'], 'Mantar zarlarında kolesterol yerine ergosterol bulunur; bitki zarlarında ise sitosterol gibi fitosteroller yer alır.'),
  ('Amfoterisin B ve nistatin gibi mantar ilaçlarının insan hücrelerine görece az zarar verip mantar hücrelerini öldürebilmesinin temel nedeni nedir?', 'Ergosterole bağlanıp zarda gözenek açmaları', ['Mantar ribozomlarının küçük alt birimine bağlanıp protein sentezini seçici olarak bozmaları', 'Yalnızca peptidoglikan sentezini durdurmaları', 'Mantar DNA\'sını kesmeleri'], 'Bu ilaçlar ergosterole insan zarındaki kolesterolden çok daha güçlü bağlanır. Zarda açılan gözeneklerden iyonların sızması mantar hücresini öldürür.'),
  ('Bir fosfolipidin zarın bir yüzündeki katmandan karşı katmana geçmesi (enine geçiş, "flip-flop") neden yanal harekete göre çok seyrek gerçekleşir?', 'Polar başın hidrofobik çekirdekten geçmesi zordur', ['Fosfolipitler zarın içinde kovalent bağlarla sabitlenmiştir', 'Zarın iki katmanı arasında geçişi engelleyen bir protein duvarı bulunması', 'Yanal hareket ATP harcanmadan olamaz'], 'Yanal hareket katman içinde kolayca olur. Enine geçişte yüklü baş grubunun hidrofobik çekirdekten geçmesi gerektiğinden bu olay kendiliğinden çok yavaştır ve flipaz gibi enzimlerle hızlandırılır.'),
  ('Normalde zarın sitoplazmaya bakan yüzünde tutulan fosfatidilserinin apoptoz sürecindeki bir hücrede dış yüzeye çıkmasının sonucu nedir?', 'Fagositlere "beni yut" işareti vermesi', ['Hücrenin bölünmeye başlaması', 'Zarın iyonlara ve suya karşı tamamen geçirimsiz hâle gelmesi', 'Hücrenin fotosentez yapmaya başlaması'], 'Fosfatidilserinin dış yüze geçmesi bir "beni ye" sinyalidir; fagositler bu hücreleri tanıyarak iltihap oluşturmadan ortadan kaldırır.'),
  ('Bir hücre zarının dış ve iç katmanlarının lipit ve protein bileşimi bakımından farklı olmasına ne ad verilir?', 'Zar asimetrisi', ['Zar akışkanlığı', 'Zar geçirgenliği', 'Zar potansiyeli'], 'İki katmanın farklı bileşime sahip olması zar asimetrisidir; örneğin glikolipitler dış, fosfatidilserin ise iç katmanda yoğunlaşır.'),
  ('Zarın yalnız bir yüzüne gevşekçe bağlı olan ve deneyde derişik tuz çözeltisiyle zar yapısı bozulmadan zardan ayrılabilen proteinlere ne ad verilir?', 'Periferik (çevresel) proteinler', ['İntegral proteinler', 'Transmembran proteinler', 'Kanal proteinleri'], 'Periferik proteinler lipit çift katmanına gömülü değildir; integral proteinlerin yüzeyine ya da lipit başlarına zayıf bağlarla tutunur. İntegral proteinleri ayırmak için ise zarı çözen deterjanlar gerekir.'),
  ('Zarı bir kez boydan boya geçen integral proteinlerde, lipit çift katmanının içinden geçen kısım genellikle nasıl bir yapıdadır?', 'Apolar amino asitlerce zengin bir alfa sarmal', ['Yalnızca yüklü amino asitlerden oluşan, suyla çevrili uzun bir zincir', 'Çift sarmallı bir DNA bölgesi', 'Şeker zincirlerinden oluşan bir dal'], 'Zarın hidrofobik iç kısmı yaklaşık 3 nm kalınlıktadır; bu mesafeyi geçmeye yetecek kadar, yan zincirleri apolar yaklaşık 20 amino asitten oluşan bir alfa sarmal en kararlı düzendir.'),
  ('Bir zar proteini hücre dışındaki bir hormona bağlandıktan sonra hücre içinde ikincil haberci olan cAMP\'yi üreten bir enzimi etkinleştiriyor. Bu senaryoda zar proteinlerinin hangi iki işlevi birlikte görülmektedir?', 'Sinyal alma (reseptör) ve enzim etkinliği', ['Madde taşıma ve hücre bağlantısı', 'Hücre tanıma ve yapısal destek', 'Kanal oluşturma ve depolama'], 'Hormonu tanıyan protein reseptör görevi görür; cAMP\'yi sentezleyen adenilat siklaz ise zara bağlı bir enzimdir. Zar proteinleri bu tür çok sayıda işlevi üstlenir.'),
  ('Bir hücrenin zar proteinleri hücre zarı düzleminde serbestçe yanal hareket edebilirken bazı proteinlerin belirli bir bölgede sabit kaldığı görülüyor. Bunun en olası nedeni hangisidir?', 'Hücre iskeletine bağlanmış olmaları', ['Bu proteinlerin zarın tamamen dışında, glikokaliksin içinde bulunması', 'Zarın o bölgede hiç lipit içermemesi', 'Bu proteinlerin karbonhidrat taşımaması'], 'Zar akışkan olsa da bazı proteinler hücre iskeletine ya da komşu hücrelere bağlanarak yerlerinde tutulur; böylece hücrenin belirli bölgelerinde özel işlevler sürdürülür.'),
  ('Bitkilerden elde edilen ve belirli şeker gruplarına özgül olarak bağlanan proteinler (lektinler), hücre yüzeyindeki hangi yapıları belirlemede araç olarak kullanılabilir?', 'Glikokaliksteki şeker zincirlerini', ['Mitokondri iç zarındaki enzimleri', 'Çekirdekteki DNA dizilerini', 'Sitoplazmadaki serbest ribozomları'], 'Lektinler belirli şeker birimlerini tanır; hücre yüzeyine bağlanmaları, glikokaliksteki şeker zincirlerinin türünü ortaya koymak için kullanılır.'),
  ('Deniz kestanelerinde bir türün spermi ancak kendi türünün yumurtasının yüzeyindeki moleküllere bağlanabiliyor. Bu tür özgüllüğünü sağlayan zar bileşenleri hangileridir?', 'Gamet yüzeyindeki tanıma glikoproteinleri', ['Mitokondri DNA\'sı', 'Hücre içindeki mikrotübüller ve bunlara bağlı motor proteinler', 'Çekirdekçikteki rRNA'], 'Gamet yüzeyindeki glikoproteinler birbirini anahtar-kilit gibi tanır; bu sayede farklı türlerin gametleri suda karışsa bile birleşemez.'),
  ('Bağırsak epitel hücrelerinde glikoz taşıyıcılarının hücrenin bağırsak boşluğuna bakan yüzünde, başka taşıyıcıların ise kana bakan yüzde kalabilmesinde sıkı bağlantıların rolü nedir?', 'Proteinlerin yanal karışmasını engellemesi', ['Glikozu doğrudan hücreler arasından kana geçirmesi', 'Komşu hücrelerin sitoplazmalarını birbirine bağlaması', 'Hücreleri bazal laminaya bağlaması'], 'Sıkı bağlantılar hücreyi kuşak gibi sardığı için zarı tepe ve taban bölgelerine ayırır; proteinler bu sınırı geçemez ve hücrenin kutupluluğu korunur.'),
  ('Kıkırdak dokusunun basınca karşı esnek ve dayanıklı olmasında, hücre dışı matrikste bol bulunan ve büyük miktarda su tutan moleküller hangileridir?', 'Proteoglikanlar', ['Fosfolipitler', 'Nükleotitler', 'Steroitler'], 'Proteoglikanlar bir çekirdek proteine bağlı çok sayıda uzun şeker zincirinden oluşur; negatif yükleri suyu çeker ve matriksin jel gibi basınca dayanmasını sağlar.'),
  ('Hayvan hücrelerinin hücre dışı matriksi ile bitki hücre duvarı karşılaştırıldığında hangisi doğrudur?', 'Matriks lifleri protein, duvar lifleri karbonhidrattır', ['İkisi de esas olarak selülozdan yapılır', 'Hayvan matriksi bitki duvarından daha serttir', 'Bitki hücre duvarında hiç karbonhidrat bulunmaması'], 'Hayvan hücre dışı matriksinde temel lifler kollajen gibi proteinlerdir; bitki hücre duvarında ise ana lif selüloz adlı polisakkarittir.'),
  ('Büyümekte olan genç bir bitki hücresinde ilk oluşan birincil hücre duvarı için hangisi doğrudur?', 'İnce ve esnektir; hücrenin büyümesine izin verir', ['Kalın ve odunlaşmıştır, hücre büyümesini tamamen durdurur', 'Yalnızca proteinlerden oluşur ve suyu hiç geçirmez', 'Hücre öldükten sonra sitoplazmanın kalıntılarından oluşur'], 'Birincil duvar, selüloz liflerinin hemiselüloz ve pektin içinde gömülü olduğu ince ve esnek bir yapıdır; hücre büyüdükçe genişleyebilir.'),
  ('Bitki hücresinde selüloz lifleri nerede sentezlenir?', 'Zardaki selüloz sentaz komplekslerince', ['Golgi cisimciğinin keseciklerinde yapılıp ekzositozla dışarı verilerek', 'Kloroplastın stromasında, fotosentez sırasında doğrudan', 'Çekirdekçikte, ribozom alt birimleriyle birlikte'], 'Selüloz, zara gömülü selüloz sentaz kompleksleri tarafından doğrudan hücre dışına doğru örülür. Hemiselüloz ve pektin ise Golgi\'de yapılıp keseciklerle dışarı gönderilir.'),
  ('Bitki hücrelerinde zarın hemen altında uzanan kortikal mikrotübüllerin dizilişi değiştirildiğinde hücrenin büyüme yönünün de değiştiği görülüyor. Bunun en uygun açıklaması nedir?', 'Selüloz liflerinin diziliş yönünü yönlendirmeleri', ['Mikrotübüllerin çekirdeği hücrenin bir ucuna itmesi', 'Mikrotübüllerin hücre duvarını doğrudan sindirmesi', 'Mikrotübüllerin kofula su pompalaması'], 'Selüloz sentaz kompleksleri zarın altındaki mikrotübüller boyunca ilerler; lifler hangi yönde dizilirse hücre o yöne dik olarak uzar.'),
  ('Bitki hücre duvarının madde geçişi bakımından hücre zarından farkı nedir?', 'Su ve küçük çözünenlere neredeyse tam geçirgendir', ['Hücre zarından daha seçici geçirgendir', 'Hiçbir maddeyi geçirmez', 'Yalnız ATP harcanarak madde geçirir'], 'Hücre duvarı gözenekli bir lif ağıdır; seçiciliği hücre zarı sağlar. Duvar asıl olarak mekanik destek ve aşırı genişlemeye karşı direnç işlevi görür.'),
  ('Gram negatif bakterilerin pek çok antibiyotiğe Gram pozitiflerden daha dirençli olmasının yapısal nedenlerinden biri hangisidir?', 'Peptidoglikanın dışında bir dış zar bulunması', ['Hücre çeperlerinin tamamen selüloz ve pektinden yapılması', 'Ribozomlarının hiç bulunmaması', 'Çekirdek zarıyla korunan DNA\'ya sahip olmaları'], 'Dış zar birçok molekülün içeri girişini sınırlar; bu yüzden bazı antibiyotikler Gram negatif bakterilerde hedeflerine ulaşamaz.'),
  ('Bir bakteri kültürüne lizozim enzimi ve izotonik şeker çözeltisi birlikte eklendiğinde bakteriler patlamadan küre biçimli, duvarsız hücrelere dönüşüyor. Bu sonuç bakteri çeperinin hangi işlevini gösterir?', 'Hücre biçimini belirleme', ['Ribozomlarda protein sentezini yürütme', 'Kalıtsal bilgiyi saklama', 'Işık enerjisini yakalama'], 'Çeper kaldırılınca çubuk biçimli bakteri bile küreye dönüşür; demek ki hücre biçimini sert peptidoglikan çeper belirler. İzotonik ortam ise osmotik patlamayı önler.'),
  ('Arkelerin hücre çeperleri bakterilerinkiyle karşılaştırıldığında hangisi doğrudur?', 'Arke çeperlerinde peptidoglikan bulunmaz', ['Arke çeperleri yalnız peptidoglikandan oluşur', 'Arke çeperleri selülozdan yapılır', 'Bütün arkelerin çeperi kitinden oluşur'], 'Arkeler peptidoglikan taşımaz; çeperleri protein tabakaları ya da yalancı peptidoglikan gibi farklı polimerlerden oluşur. Bu yüzden penisiline duyarlı değildirler.'),
  ('Difüzyonla bir maddenin belirli bir uzaklığı alması için geçen süre, uzaklığın karesiyle orantılıdır. Bir molekülün 10 µm\'yi 0,1 saniyede aldığı varsayılırsa 30 µm\'yi yaklaşık ne kadar sürede alır?', '0,9 saniye', ['0,3 saniye', '0,6 saniye', '0,45 saniye'], 'Uzaklık 3 katına çıkınca süre 3² = 9 katına çıkar: 0,1 × 9 = 0,9 saniye. Bu yüzden difüzyon yalnız kısa mesafelerde etkili bir taşıma yoludur.'),
  ('Bir diyaliz torbasının içine nişasta çözeltisi konup torba iyotlu suya batırılıyor. Bir süre sonra torbanın içi mavi-mora boyanırken dışarıdaki su renk değiştirmiyor. Bu sonuç için en doğru açıklama hangisidir?', 'İyot içeri girmiş, nişasta dışarı çıkamamıştır', ['Nişasta torbadan çıkıp dışarıdaki iyotla tepkimeye girmiş, sonra geri dönmüştür', 'Torba zarı iyot ve nişastanın ikisini de geçirmemiştir', 'Su torbaya girmiş, iyot dışarıda kalmıştır'], 'Renk değişimi nişasta ile iyotun bir araya geldiği yerde olur. Yalnız torbanın içi renklendiği için küçük iyot molekülleri içeri girmiş, büyük nişasta molekülleri zarı geçememiştir.'),
  ('1890\'larda pek çok maddenin hücreye giriş hızını karşılaştıran Ernest Overton, yağda çözünürlüğü yüksek maddelerin hücreye daha hızlı girdiğini fark etti. Bu gözlemden zar hakkında hangi sonuç çıkarılmıştır?', 'Zarın lipit yapısında olduğu', ['Zarın yalnız proteinden yapıldığı', 'Zarın tamamen su olduğu', 'Zarın her maddeyi aynı hızda geçirdiği'], 'Yağda çözünen maddelerin daha kolay geçmesi, zarın lipitçe zengin bir tabaka olduğunu düşündürdü. Bu, zar yapısına ilişkin ilk önemli ipuçlarından biridir.'),
  ('Yüklü bir iyonun hücre zarından geçiş yönünü belirleyen etken için hangisi en doğrudur?', 'Derişim farkı ve zar potansiyeli birlikte', ['Yalnızca iyonun hücre içindeki derişimi', 'Yalnızca iyonun büyüklüğü ve sahip olduğu su kılıfının kalınlığı', 'İyonun suda çözünüp çözünmemesi'], 'İyonlar için itici güç elektrokimyasal gradyandır: derişim farkı ve zar potansiyeli birlikte iyonun hangi yöne pasif olarak hareket edeceğini belirler.'),
  ('Na⁺, K⁺ ve Cl⁻ gibi küçük iyonların, oksijenden daha küçük olabildikleri hâlde lipit çift katmanından neredeyse hiç geçememesinin nedeni nedir?', 'Yüklü ve su kılıflı olmaları', ['Hücre içinde hiç bulunmamaları', 'Zardaki kolesterol molekülleriyle kalıcı kovalent bağ yapmaları', 'Moleküllerin en büyükleri olmaları'], 'İyonlar yüklüdür ve bir su kılıfıyla çevrilidir; zarın su sevmeyen iç kısmına girmeleri enerji bakımından çok zordur. Bu yüzden kanal ya da taşıyıcı proteinlere gereksinim duyarlar.'),
  ('Kanal proteinleri ile taşıyıcı proteinler karşılaştırıldığında, kanallarla taşımanın çok daha hızlı olmasının nedeni nedir?', 'Biçim değiştirmeden sürekli geçit açmaları', ['Kanalların ATP harcayarak maddeleri itmesi', 'Kanalların yalnızca büyük molekülleri taşıması', 'Taşıyıcıların zarın dışında bulunması'], 'Açık bir kanaldan saniyede milyonlarca iyon akabilir. Taşıyıcılar ise her molekülü bağlayıp biçim değiştirerek taşıdığı için çok daha yavaştır.'),
  ('Bir hücrenin zarına çok sayıda gramisidin kanalı eklenerek iyonların serbestçe geçmesi sağlanıyor. Bu durumun hücre için başlıca zararı ne olur?', 'İyon farklarının ortadan kalkması', ['Hücrede protein sentezinin hızlanması', 'Hücre zarının kalınlaşması', 'Hücreye su girişinin tamamen durması'], 'Hücre birçok işlevi için Na⁺, K⁺ ve H⁺ farklarına bağımlıdır. İyonlar serbest geçince bu farklar sönümlenir ve pompaların harcadığı enerji boşa gider.'),
  ('Alyuvar zarındaki glikoz taşıyıcısı doğal D-glikozu kolayca taşırken onun ayna görüntüsü olan L-glikozu hemen hiç taşımaz. Bu durum taşıyıcı proteinlerin hangi özelliğini gösterir?', 'Özgüllük', ['Doygunluk', 'Enerji bağımlılığı', 'Akışkanlık'], 'Taşıyıcının bağlanma bölgesi belirli bir üç boyutlu biçime uyar; atomları aynı olsa bile ayna görüntüsü molekül bu bölgeye uymaz.'),
  ('Glikozun kolaylaştırılmış difüzyonla hücreye girdiği bir deneyde ortama yapıca glikoza çok benzeyen başka bir şeker eklendiğinde glikoz girişinin yavaşladığı görülüyor. En uygun açıklama nedir?', 'İki şekerin aynı taşıyıcı için yarışması', ['Eklenen şekerin hücre zarını eritmesi', 'Glikozun hücre içinde hemen ATP\'ye dönüşmesi', 'Hücre zarının ortamdaki şekerler nedeniyle kalınlaşması'], 'Benzer yapılı moleküller aynı taşıyıcının bağlanma bölgesine tutunabilir; taşıyıcıların bir kısmı diğer şekerle meşgul olduğundan glikoz taşınması azalır (rekabet).'),
  ('Kolaylaştırılmış difüzyonla çalışan bir taşıyıcı, ATP harcamadığı hâlde maddeyi nasıl karşı tarafa geçirir?', 'Maddeyi bağlayınca biçim değiştirip bağlanma yerini öbür yüze açarak', ['Zarda kalıcı ve her zaman açık bir delik oluşturarak', 'Maddeyi bir keseciğe sararak', 'Maddeyi kimyasal olarak parçalayıp öbür tarafta yeniden yaparak'], 'Taşıyıcılar bağlanma bölgesini dönüşümlü olarak zarın bir yüzüne, sonra öbür yüzüne açar. Net taşınma derişim farkı yönünde olur; bu yüzden enerji gerekmez.'),
  ('Osmotik basınç, çözünen maddenin türüne değil çözeltideki tanecik sayısına bağlıdır. Buna göre suda tamamen iyonlarına ayrışan 0,1 M NaCl çözeltisi ile 0,15 M glikoz çözeltisi yarı geçirgen bir zarla ayrılırsa su hangi yöne net olarak geçer?', 'Glikoz çözeltisinden NaCl çözeltisine', ['NaCl çözeltisinden glikoz çözeltisine', 'Hiçbir yöne geçmez, çözeltiler eşittir', 'Önce NaCl\'ye, sonra eşit hızda geri döner'], '0,1 M NaCl yaklaşık 0,2 mol tanecik (Na⁺ ve Cl⁻) verir; 0,15 M glikoz ise 0,15 mol tanecik içerir. Su, tanecik derişimi daha yüksek olan NaCl tarafına geçer.'),
  ('Yalnız suyu geçiren bir zarla ayrılmış iki bölmeden birinde %10\'luk, diğerinde %20\'lik şeker çözeltisi vardır. Zarın hem suyu hem de şekeri geçirebilen bir zarla değiştirildiği düşünülürse uzun sürede ne olur?', 'İki bölmedeki derişimler eşitlenir ve sıvı düzeyleri aynı kalır', ['%20\'lik taraftaki sıvı düzeyi kalıcı olarak yükselir', 'Bütün su %10\'luk tarafa geçer', 'Şeker yalnız %10\'luk taraftan %20\'lik tarafa geçer'], 'Zar şekeri de geçirirse şeker kendi derişim farkı yönünde yayılır; derişimler eşitlenince kalıcı bir osmotik fark kalmaz. Osmotik basınç ancak çözüneni geçirmeyen zarlarda oluşur.'),
  ('Plazmoliz geçirmiş bir bitki hücresinde hücre zarı ile hücre duvarı arasındaki boşluğu ne doldurur?', 'Dış ortamdaki çözelti', ['Hava', 'Sitoplazma', 'Vakum'], 'Hücre duvarı tam geçirgen olduğundan zar çekildikçe aradaki boşluğa dış ortamdaki çözelti dolar; bu boşluk boş ya da hava dolu değildir.'),
  ('Eşit kütlede patates şeritleri farklı derişimlerdeki sakaroz çözeltilerine bırakılıyor. 0,2 M\'de şeritler kütle kazanıyor, 0,4 M\'de kütle kaybediyor, 0,3 M\'de ise kütle değişmiyor. Bu sonuçtan hangi çıkarım yapılır?', 'Patates hücrelerinin içeriği yaklaşık 0,3 M sakarozla izotoniktir', ['Patates hücreleri 0,2 M\'de plazmoliz geçirmiştir', 'Sakaroz patates hücrelerine serbestçe girmektedir', '0,4 M çözelti patatese göre hipotoniktir'], 'Kütle değişmeyen derişimde net su alışverişi olmaz; bu, hücre içeriğinin o çözeltiyle izotonik olduğunu gösterir. Daha seyrek çözeltide su alınır, daha derişikte su kaybedilir.'),
  ('Sodyum-potasyum pompasının her döngüde hücreden dışarı içeri aldığından bir fazla pozitif yük çıkarması pompanın hangi özelliğini gösterir?', 'Elektrojenik olmasını', ['Pasif çalışmasını', 'Yalnız anyon taşımasını', 'ATP üretmesini'], '3 Na⁺ çıkarılıp 2 K⁺ alındığından her döngüde dışarıya net bir pozitif yük gider; bu, zar potansiyeline doğrudan katkı yapan elektrojenik bir pompadır.'),
  ('Bir hayvan hücresinde Na⁺/K⁺ pompası ouabain adlı maddeyle tamamen durdurulursa zamanla hücrenin hacmi nasıl değişir?', 'Na⁺ birikir, su girer ve hücre şişer', ['Hücre su kaybedip büzülür', 'Hacim hiç değişmez', 'Hücre önce şişer, sonra kendiliğinden eski hacmine döner'], 'Pompa durunca içeri sızan Na⁺ dışarı atılamaz; hücre içinde tanecik derişimi arttığından su osmozla içeri girer ve hücre şişer. Pompa bu yolla hücre hacmini de denetler.'),
  ('Hücre içi sıvıdaki serbest Ca²⁺ derişiminin hücre dışındakinden yaklaşık on bin kat düşük tutulması başlıca neyle sağlanır?', 'Zar ve ER\'deki ATP harcayan Ca²⁺ pompalarıyla', ['Ca²⁺ iyonlarının zardan hiç geçememesiyle', 'Ca²⁺\'un hücre içinde sürekli yeniden üretilmesiyle', 'Ca²⁺ iyonlarının kanallardan içeri sürekli akmasıyla'], 'Ca²⁺ pompaları iyonu hücre dışına ve ER içine taşır. Bu çok düşük düzey sayesinde Ca²⁺ kanallarının kısa süre açılması bile güçlü bir sinyal oluşturur.'),
  ('Kanser hücrelerinin zamanla birden çok ilaca birden direnç kazanmasında rol oynayan bir mekanizma, zardaki bazı taşıyıcıların sayısının artmasıdır. Bu taşıyıcılar nasıl çalışır?', 'İlaçları ATP harcayarak hücre dışına pompalar', ['İlaçları hücre içinde kalıcı olarak depolar', 'İlaçların hücreye girişini kolaylaştırır', 'İlaçları hücre çekirdeğine taşıyıp DNA\'ya bağlar'], 'ABC taşıyıcı ailesinden P-glikoprotein gibi pompalar farklı yapıdaki ilaçları ATP enerjisiyle dışarı atar; hücre içi ilaç derişimi düşük kalır.'),
  ('Su basmış, havasız topraklarda yetişen bitkilerin köklerinin mineral alımında ilk aksayan süreç hangisidir?', 'ATP gerektiren aktif mineral alımı', ['Suyun osmozla alınması', 'Oksijenin kök hücrelerine difüzyonla girmesi', 'Kök hücrelerinin plazmolizi'], 'Oksijen yetersizliğinde kök hücreleri oksijenli solunumla yeterli ATP üretemez; derişim farkına karşı yapılan mineral alımı bu nedenle azalır.'),
  ('Bağırsak hücrelerinde Na⁺/K⁺ pompası durdurulduğunda, bu pompa glikoz taşımadığı hâlde Na⁺-glikoz ortak taşıyıcısıyla glikoz alımının bir süre sonra durmasının nedeni nedir?', 'Pompa durunca Na⁺ farkının sönmesi', ['Pompanın aynı zamanda glikoz da taşıması', 'Glikozun hücre içinde birikip zardaki bütün taşıyıcıları tıkaması', 'Ortak taşıyıcının doğrudan ATP kullanması'], 'Ortak taşıyıcı, içeri doğru akan Na⁺\'un enerjisini kullanır. Bu Na⁺ farkını Na⁺/K⁺ pompası oluşturduğundan pompa durunca ikincil taşıma da durur.'),
  ('Bitkilerde floeme sakaroz yüklenirken sakarozun derişim farkına karşı hücreye alınması, H⁺ pompasının oluşturduğu proton farkına bağlıdır. Bu taşıma hangi türdendir?', 'H⁺-sakaroz simportu', ['Sakaroz uniportu', 'Na⁺/K⁺ antiportu', 'Sakaroz pinositozu'], 'Protonlar derişim farkı yönünde içeri girerken sakarozu da aynı yönde birlikte taşır; enerji kaynağı H⁺ farkı olduğundan bu bir ikincil aktif simporttur.'),
  ('Kalp kası hücrelerinde içeri giren 3 Na⁺ iyonuna karşılık 1 Ca²⁺ iyonunu hücre dışına atan taşıyıcı hangi taşıma türüne örnektir?', 'İkincil aktif antiport', ['Birincil aktif simport', 'Kolaylaştırılmış uniport', 'Basit difüzyon'], 'Na⁺ derişim farkı yönünde içeri girerken Ca²⁺ derişim farkına karşı dışarı çıkar. Enerji Na⁺ farkından geldiği için ikincil aktif, yönler zıt olduğu için antiporttur.'),
  ('Bakterilerde laktoz taşıyıcısı (laktoz permeaz), protonların hücreye girişiyle birlikte laktozu da içeri alır. Proton farkını ortadan kaldıran bir madde eklendiğinde ne beklenir?', 'Laktoz derişim farkına karşı biriktirilemez', ['Laktoz alımı iki katına çıkar', 'Bakteri laktozu ATP\'ye çevirmeye başlar', 'Laktoz hücre dışına pompalanmaya başlar'], 'Simport, proton farkının enerjisine bağımlıdır; fark yok edilince laktoz hücre içinde dış ortamdan daha yüksek derişime ulaşacak biçimde biriktirilemez.'),
  ('Birincil ve ikincil aktif taşıma karşılaştırıldığında hangisi doğrudur?', 'Yalnız birincil olan ATP\'yi doğrudan kullanır', ['İkisi de ATP\'yi doğrudan parçalar', 'İkincil aktif taşıma enerji gerektirmeyen pasif bir olaydır', 'Birincil aktif taşıma enerji gerektirmez'], 'Birincil pompalar ATP\'yi kendileri hidroliz eder. İkincil taşıyıcılar ise bu pompaların oluşturduğu iyon farklarını kullandığından ATP\'ye dolaylı yoldan bağımlıdır.'),
  ('Pinositoz ile reseptör aracılı endositoz karşılaştırıldığında hangisi doğrudur?', 'Yalnız ikincisi molekülleri seçerek alır', ['İkisi de enerji harcamadan gerçekleşir', 'Pinositoz yalnızca katı taneciklerin alınmasıdır', 'Reseptör aracılı endositoz maddeleri hücre dışına ekzositozla verir'], 'Pinositozda çevredeki sıvı içinde ne varsa alınır. Reseptör aracılı endositozda ise yalnız reseptöre bağlanan moleküller yoğunlaştırılarak alınır.'),
  ('Kan damarlarının iç yüzeyini döşeyen hücrelerin bazı maddeleri bir yüzden kesecikle alıp hücreyi boydan boya geçirerek öbür yüzden ekzositozla bırakmasına ne ad verilir?', 'Transsitoz', ['Pinositoz', 'Plazmoliz', 'Otofaji'], 'Transsitozda madde hücrenin bir yüzünde endositozla alınır, kesecik hâlinde hücreyi geçer ve karşı yüzde ekzositozla dışarı verilir.'),
  ('Grip virüsü gibi zarflı bazı virüsler hücreye endositozla alındıktan sonra, endozomun içi asitleştiğinde zarlarını endozom zarıyla kaynaştırıp genetik maddelerini sitoplazmaya bırakır. Endozomların asitleşmesini engelleyen bir ilacın etkisi ne olur?', 'Genetik madde sitoplazmaya geçemez', ['Virüsün hücreye bağlanması kolaylaşır', 'Virüs doğrudan çekirdeğe geçer', 'Virüs ekzositozla hücreden daha hızlı çıkar ve komşu hücrelere yayılır'], 'Kaynaşma düşük pH ile tetiklendiği için asitleşme önlenirse virüs endozomdan kaçamaz ve çoğu zaman lizozomlarda yıkılır.'),
  ('Pankreastaki insülin salgılayan hücreler insülini salgı keseciklerinde biriktirir ve kan şekeri yükselince bir anda salar. Bu salgılama biçiminin hücreye kazandırdığı üstünlük nedir?', 'Gereken anda hızlı ve yoğun bir salım yapabilmek', ['Hormonu hiç enerji harcamadan üretebilmek', 'Hormonun hücre içinde sindirilmesini sağlamak', 'Salgı keseciklerini Golgi\'ye gerek kalmadan yapmak'], 'Düzenlenmiş salgılamada ürün önceden hazırlanıp keseciklerde bekletilir; sinyal gelince birçok kesecik aynı anda zarla kaynaşır ve yanıt çok hızlı olur.'),
  ('Düzenlenmiş ekzositozda keseciklerin hücre zarıyla kaynaşmasını tetikleyen en yaygın hücre içi sinyal hangisidir?', 'Sitoplazmada Ca²⁺ derişiminin artması', ['Hücre içindeki K⁺ derişiminin artması', 'Çekirdek zarının parçalanması', 'ATP derişiminin sıfıra inmesi'], 'Sinir uçlarında, salgı hücrelerinde ve mast hücrelerinde zar kanallarından ya da ER\'den gelen Ca²⁺ artışı, beklemedeki keseciklerin zarla kaynaşmasını başlatır.'),
  ('Bir hücre çok yoğun ekzositoz yaptığı hâlde hücre zarının yüzey alanının uzun vadede aşırı büyümemesi nasıl açıklanır?', 'Endositozla zar geri alınır', ['Zarın fazla kısmının dışarı kopup atılması', 'Ekzositozun zarı inceltmesi', 'Zar lipitlerinin hemen ATP\'ye dönüşmesi'], 'Ekzositozla zara eklenen kısımlar endositozla geri alınır ve yeniden kullanılır; bu zar geri dönüşümü sayesinde hücrenin yüzeyi dengede kalır.'),
  ('Çekirdek zarındaki iki zar arasındaki boşluk (perinükleer boşluk) hangi hücre bölmesiyle doğrudan bağlantılıdır?', 'ER\'nin iç boşluğuyla', ['Mitokondri matriksiyle', 'Sitoplazmanın sıvı kısmıyla', 'Lizozomların içiyle'], 'Dış çekirdek zarı ER zarıyla kesintisiz olduğundan iki zar arasındaki boşluk da ER\'nin iç boşluğunun (lümeninin) devamıdır.'),
  ('Büyük proteinlerin çekirdeğe alınabilmesi için üzerlerinde bulunması gereken ve çoğunlukla pozitif yüklü birkaç amino asitten oluşan kısa diziye ne ad verilir?', 'Çekirdek yerleşim sinyali', ['Sinyal tanıma parçacığı', 'Kodon dizisi', 'Dur kodonu'], 'Çekirdek yerleşim sinyali taşıyan proteinler importin adlı taşıyıcılar tarafından tanınır ve çekirdek porlarından aktif olarak içeri alınır.'),
  ('Çekirdek porlarından geçiş için hangisi doğrudur?', 'Küçükler serbest, büyükler seçici olarak geçer', ['Porlar her büyüklükteki molekülü hiçbir seçicilik göstermeden geçirir', 'Porlardan yalnızca su ve iyonlar geçebilir', 'Porlar yalnız mitoz sırasında açılır'], 'Por kompleksi küçük molekülleri ve iyonları difüzyonla geçirir; büyük proteinler ve RNA-protein kompleksleri ise taşıyıcı proteinlerle, enerji harcanarak taşınır.'),
  ('Ribozom alt birimlerinin oluşumunda çekirdek ile sitoplazma arasındaki iş bölümü hangi seçenekte doğru verilmiştir?', 'Ribozom proteinleri sitoplazmada yapılır, çekirdekçikte rRNA ile birleşir', ['Ribozomlar tamamen sitoplazmada, rRNA olmadan kurulur', 'Ribozom proteinleri çekirdekçikte, rRNA ise sitoplazmada yapılır', 'Alt birimler mitokondride birleştirilip çekirdeğe taşınır'], 'Ribozom proteinleri sitoplazmada sentezlenip çekirdeğe alınır; çekirdekçikte rRNA ile birleşerek alt birimleri oluşturur ve alt birimler porlardan ayrı ayrı sitoplazmaya çıkar.'),
  ('Bitkilerde floemin kalburlu borularını oluşturan olgun hücreler canlı oldukları hâlde çekirdek taşımaz. Bu hücrelerin protein gereksinimleri nasıl karşılanır?', 'Komşu arkadaş hücrelerinden plazmodezmalarla', ['Kendi çekirdekçiklerinde yeni ribozom yaparak', 'Ksilemden gelen suyla çözünmüş protein alarak', 'Kloroplastlarındaki DNA\'yı kullanarak bütün proteinleri yaparak'], 'Kalburlu boru hücreleri olgunlaşırken çekirdeklerini ve birçok organellerini yitirir; yanlarındaki çekirdekli arkadaş hücreler onların metabolik gereksinimlerini plazmodezmalar yoluyla karşılar.'),
  ('Paramesyum gibi siliyatlarda iki tür çekirdek bulunur. Bunlardan büyük olanı (makronükleus) hangi işlevi üstlenir?', 'Günlük işleyişi yöneten genleri ifade etmek', ['Yalnızca eşeyli üremede kalıtsal bilgiyi eşe aktarmak', 'Yalnızca ribozom üretmek', 'Hücrenin hareket yönünü belirlemek'], 'Makronükleus hücrenin günlük işleyişini yönetir; küçük çekirdek (mikronükleus) ise eşeyli üreme sırasında kalıtsal bilgi alışverişinde kullanılır.'),
  ('Mitokondri proteinlerinin büyük çoğunluğu için hangisi doğrudur?', 'Çekirdekte şifrelenir, sonradan mitokondriye alınır', ['Mitokondri DNA\'sında şifrelenir ve tamamı mitokondri ribozomlarında yapılır', 'Golgi\'de yapılıp salgı kesecikleriyle mitokondriye gider', 'Mitokondri zarından difüzyonla kendiliğinden içeri sızar'], 'Mitokondri DNA\'sı yalnız az sayıda proteini şifreler; yüzlerce mitokondri proteini çekirdek genlerinden üretilir ve uçlarındaki hedefleme dizileri sayesinde zar kanallarıyla mitokondriye aktarılır.'),
  ('Sitoplazmada sentezlenen bir proteinin mitokondriye alınabilmesi için genellikle nesine ihtiyaç vardır?', 'Mitokondri hedefleme dizisine', ['Mannoz-6-fosfat işaretine', 'Çekirdek yerleşim sinyaline', 'Glikolipit çapasına'], 'Mitokondri proteinlerinin ucundaki hedefleme dizisi mitokondri dış ve iç zarındaki taşıma kompleksleri tarafından tanınır; protein içeri alındıktan sonra bu dizi çoğunlukla kesilir.'),
  ('Granüllü ER\'de yapılan bazı proteinler Golgi\'ye gönderilse bile, uçlarındaki dört amino asitlik bir işaret sayesinde geri yakalanıp ER\'ye döndürülür. Bu düzenek hangi proteinlerin ER\'de kalmasını sağlar?', 'ER\'de görevli katlanma yardımcılarının', ['Hücre dışına salgılanacak hormonların ve sindirim enzimlerinin', 'Lizozom enzimlerinin', 'Hücre zarı reseptörlerinin'], 'ER\'de görevli proteinler (örneğin katlanmaya yardım eden şaperonlar) uçlarındaki geri tutma işareti sayesinde Golgi\'den ER\'ye geri taşınır; böylece kaçsalar bile ER\'de kalırlar.'),
  ('Normalde sitoplazmada kalan bir proteinin genine ER sinyal peptidi ekleyen bir araştırmacı, bu proteinin hücre dışında birikmeye başladığını görüyor. Bu sonuç neyi kanıtlar?', 'Salgı için sinyal dizisinin yeterli olduğunu', ['Hücrenin bütün proteinlerinin zaten hücre dışına salgılandığını', 'Sinyal peptidinin proteini çekirdeğe gönderdiğini', 'Proteinin hücre dışında yeniden sentezlendiğini'], 'Başka hiçbir değişiklik yapılmadan yalnız sinyal peptidinin eklenmesi proteini salgı yoluna sokmuştur; demek ki ER\'ye girişi ve varsayılan salgı yolunu bu dizi belirler.'),
  ('Bir hücredeki serbest ribozomlar ile ER\'ye bağlı ribozomlar karşılaştırıldığında hangisi doğrudur?', 'Yapıca aynıdır; yeri proteinin sinyaline bağlıdır', ['ER\'ye bağlı ribozomların yapısı tamamen farklıdır', 'Serbest ribozomlar yalnızca bakterilerde bulunur', 'Bir ribozom bir kez ER\'ye bağlanınca hücre ölene kadar oradan ayrılamaz'], 'Ribozomlar arasında yapısal fark yoktur. Sentezlenen polipeptit ER sinyal dizisi taşıyorsa ribozom ER\'ye bağlanır; çeviri bitince yeniden serbest kalabilir.'),
  ('Pek çok salgı proteininin kararlı yapısında bulunan disülfit köprülerinin oluşumu hücrede genellikle nerede gerçekleşir?', 'ER\'nin iç boşluğunda', ['Sitoplazmanın sıvı kısmında', 'Çekirdekçikte', 'Mitokondri matriksinde'], 'ER\'nin iç ortamı sitoplazmaya göre daha yükseltgendir ve disülfit izomeraz gibi enzimler içerir; bu yüzden disülfit bağları burada kurulur.'),
  ('ER\'de doğru katlanamayan proteinler sonunda nasıl ortadan kaldırılır?', 'Ubikitinlenip proteazomda yıkılır', ['Doğrudan çekirdeğe gönderilip burada nükleotitlere dönüştürülür', 'Hücre zarına yerleştirilip orada bekletilir', 'ER içinde kalıcı olarak depolanıp hücre bölünürken atılır'], 'ER kalite denetimi bozuk proteinleri sitoplazmaya geri aktarır; buradaki ubikitin işaretli proteinler proteazom adlı protein yıkıcı kompleks tarafından parçalanır.'),
  ('Hücrede yıkılacak proteinlere küçük bir protein zincir hâlinde eklenerek onları sitoplazmadaki fıçı biçimli protein yıkıcı komplekse yönlendirir. Bu işaret proteini ve yıkıcı kompleks sırasıyla hangileridir?', 'Ubikitin ve proteazom', ['Klatrin ve lizozom', 'Histon ve nükleozom', 'Aktin ve sentrozom'], 'Ubikitin zincirleri proteini işaretler; proteazom bu işareti tanıyıp proteini küçük peptitlere parçalar. Bu yol, lizozomdan bağımsız bir yıkım sistemidir.'),
  ('Tunikamisin adlı antibiyotik ER\'de proteinlere şeker zinciri eklenmesini engeller. Bu madde verilen hücrelerde hangisi beklenir?', 'ER\'de yanlış katlanmış proteinlerin birikmesi', ['Hücre zarının tamamen glikoprotein kaplı olması', 'Mitokondrilerde ATP üretiminin artması', 'Çekirdek zarının kaybolması'], 'Şeker zincirleri birçok proteinin doğru katlanmasına ve kalite denetiminden geçmesine yardım eder. Bu eklenti olmadan pek çok protein yanlış katlanır ve ER\'de birikerek stres yanıtını tetikler.'),
  ('Hücre zarında bulunacak transmembran proteinler zara nasıl yerleştirilir?', 'Sentezlenirken ER zarına gömülerek', ['Sitoplazmada tamamen sentezlenip hücre zarına dışarıdan yapışarak', 'Çekirdekte üretilip porlardan çıkarak', 'Mitokondri tarafından doğrudan zara püskürtülerek'], 'Zar proteinleri sentezlenirken hidrofobik bölgeleri ER zarına gömülür; ER\'den Golgi\'ye, oradan keseciklerle hücre zarına giderken zardaki konumlarını korurlar.'),
  ('ER kesecikleriyle zara giden bir transmembran proteinin ER\'nin iç boşluğuna bakan kısmı, hücre zarına ulaştığında hangi yöne bakar?', 'Hücre dışına', ['Sitoplazmaya', 'Çekirdeğe', 'Mitokondri matriksine'], 'Kesecik hücre zarıyla kaynaşınca keseciğin iç yüzü hücre zarının dış yüzüne dönüşür; bu yüzden ER lümenine bakan kısım sonunda hücre dışına bakar.'),
  ('Uzun süre barbitürat gibi yatıştırıcı ilaçlar kullanan kişilerde aynı etkiyi elde etmek için dozun artırılması gerekir (tolerans). Bu durumun karaciğer hücrelerindeki hücresel açıklaması hangisidir?', 'Düz ER\'nin çoğalması', ['Lizozomların tamamen kaybolması', 'Ribozomların hücre zarına taşınıp ilacı bağlaması', 'Çekirdek zarının kalınlaşması'], 'İlaçlar karaciğer hücrelerinde düz ER\'nin ve ilgili detoks enzimlerinin artmasına yol açar; ilaç daha hızlı yıkıldığı için aynı doz daha zayıf etki gösterir.'),
  ('Düz ER\'deki sitokrom P450 enzimleri yağda çözünen ilaçlara hidroksil (–OH) grubu ekler. Bu değişikliğin vücut için yararı nedir?', 'Suda çözünürlüğü artırıp atılımı kolaylaştırmak', ['Maddeyi daha yağda çözünür yapıp yağ dokusunda uzun süre biriktirmek', 'Maddeyi doğrudan ATP\'ye dönüştürmek', 'Maddeyi proteine dönüştürüp kasta depolamak'], 'Polar grup eklenen maddeler suda daha iyi çözünür; böylece böbreklerle idrarla ya da safrayla daha kolay atılırlar.'),
  ('Golgi cisimciğinin ER\'den gelen keseciklerin kaynaştığı yüzü ile salgı keseciklerinin ayrıldığı yüzü sırasıyla nasıl adlandırılır?', 'Cis yüzü ve trans yüzü', ['Trans yüzü ve cis yüzü', 'Dış yüz ve iç yüz', 'Apikal yüz ve bazal yüz'], 'Golgi kutupludur: ER\'ye bakan giriş yüzü cis, hücre zarına bakan ve paketlenmiş keseciklerin ayrıldığı çıkış yüzü trans olarak adlandırılır.'),
  ('Lizozom enzimlerine mannoz-6-fosfat işaretini ekleyen enzimin bozuk olduğu kalıtsal bir hastalıkta, hastanın kan ve doku sıvılarında lizozom enzimlerinin yüksek bulunmasının nedeni nedir?', 'İşaretsiz enzimlerin salgılanması', ['Lizozomların patlayıp bütün enzimlerini doğrudan kana boşaltması', 'Enzimlerin çekirdekte aşırı üretilmesi', 'Enzimlerin hücre zarından difüzyonla sızması'], 'İşaret yoksa enzimler lizozoma yönlendirilemez ve salgı yolundan hücre dışına verilir; lizozomlar ise boş kalır ve sindirilemeyen maddeler birikir (I-hücre hastalığı).'),
  ('Bitki hücrelerinde Golgi cisimciği hayvan hücrelerinden farklı olarak çoğunlukla nasıl bulunur ve hangi adla anılır?', 'Dağınık, çok sayıda diktiyozom', ['Çekirdeğin içinde tek bir sentrozom', 'Kloroplastın içinde tilakoit', 'Hücre duvarına gömülü plazmodezma'], 'Bitki hücrelerinde Golgi yığınları dağınık hâlde ve çok sayıda bulunur; her birine diktiyozom denir. Hücre duvarı polisakkaritlerinin büyük kısmı bunlarda yapılır.'),
  ('Pankreasta önce tek zincirli öncül bir molekül olarak üretilen insülin, etkin hormona salgı keseciklerinde nasıl dönüşür?', 'Bir parçanın kesilip çıkarılmasıyla', ['Molekülün iki katına uzatılmasıyla', 'Çekirdekte yeniden yazılmasıyla', 'Lizozomlarda tamamen yıkılmasıyla'], 'Proinsülin trans Golgi ve salgı keseciklerindeki proteazlarla kesilir; ortadaki C-peptit çıkarılır ve disülfit köprüleriyle bağlı iki zincirli insülin oluşur.'),
  ('Lizozomun iç ortamının pH 4,5–5 dolayında, yani sitoplazmadan çok daha asidik tutulması nasıl sağlanır?', 'Zardaki pompaların içeri H⁺ taşımasıyla', ['Lizozom enzimlerinin kendiliğinden asit üretmesiyle', 'Sitoplazmadaki asidin difüzyonla lizozoma dolmasıyla', 'Lizozomun içine sürekli mide asidi taşınmasıyla'], 'Lizozom zarındaki V tipi H⁺-ATPazlar protonları derişim farkına karşı içeri pompalar; bu asidik ortam hidrolitik enzimlerin çalışması için gereklidir.'),
  ('Lizozom zarının kendi içindeki güçlü sindirim enzimlerinden zarar görmemesine katkı yapan özelliklerden biri hangisidir?', 'Zar proteinlerinin şekerle örtülü olması', ['Zarın tamamen selülozdan yapılmış olması', 'Zarın hiç protein içermemesi', 'Enzimlerin zarın dış yüzünde bulunması'], 'Lizozom zar proteinlerinin iç yüzü çok sayıda şeker zinciriyle örtülüdür; bu kalkan proteazların zar proteinlerine ulaşmasını zorlaştırır.'),
  ('Uzun süre silis (kuvars) tozu soluyan madencilerde makrofajların bu tanecikleri yutmasının ardından akciğerde hasar oluşması nasıl açıklanır?', 'Taneciklerin lizozom zarını delmesi', ['Taneciklerin mitokondride ATP üretimini artırması', 'Silisin hücre zarını kalınlaştırması', 'Taneciklerin çekirdekte yeni DNA oluşturması'], 'Silis tanecikleri sindirilemez; lizozom zarını bozarak enzimlerin sızmasına ve makrofajın ölmesine yol açar. Açığa çıkan maddeler iltihabı ve bağ dokusu artışını (fibrozu) tetikler.'),
  ('Otofaji sırasında yıkılacak organeli saran ve sonra lizozomla kaynaşan çift zarlı keseciğe ne ad verilir?', 'Otofagozom', ['Fagozom', 'Peroksizom', 'Salgı keseciği'], 'Otofajide sitoplazmanın bir bölümü ya da bir organel çift zarlı otofagozomla çevrilir; otofagozom lizozomla kaynaşınca içerik sindirilir. Fagozom ise hücre dışından alınan maddeyi içerir.'),
  ('Hücre içindeki protein yıkımında proteazom ile lizozom karşılaştırıldığında hangisi doğrudur?', 'Proteazom tek tek proteinleri, lizozom büyük yapıları yıkar', ['Proteazom bütün organelleri tek seferde sindirir', 'Lizozomlar yalnız ubikitinli tek proteinleri tanır', 'Proteazom da lizozom da zarla çevrili, hidrolitik enzim dolu organellerdir'], 'Proteazom zarsız bir protein kompleksidir ve ubikitinle işaretlenmiş tek tek proteinleri parçalar. Lizozom ise zarlı bir organeldir ve organellerden bakterilere kadar büyük yapıları sindirebilir.'),
  ('Peroksizomların yağ metabolizmasındaki özel görevlerinden biri hangisidir?', 'Çok uzun zincirli yağ asitlerini kısaltmak', ['Yağ asitlerinden doğrudan protein üretmek', 'Kolesterolü hücre dışına salgılamak', 'Fosfolipitleri çekirdeğe taşımak'], 'Çok uzun zincirli yağ asitleri önce peroksizomlarda beta oksidasyonla kısaltılır; kısalan zincirler mitokondriye geçerek yıkımı tamamlanır.'),
  ('Peroksizomların iç zar sistemine dahil edilmemesinin nedenlerinden biri hangisidir?', 'Proteinlerinin çoğunu doğrudan sitoplazmadan almaları', ['Çift zarlı ve kendi DNA\'larına sahip olmaları', 'Hiç zar taşımamaları', 'Yalnız bitki hücrelerinde bulunmaları'], 'Peroksizom proteinleri serbest ribozomlarda yapılır ve uçlarındaki özel bir işaretle sitoplazmadan doğrudan alınır; Golgi\'den gelen keseciklerle beslenen lizozomlardan bu yönüyle ayrılır.'),
  ('"Lorenzo\'nun Yağı" filmine konu olan adrenolökodistrofi hastalığında çok uzun zincirli yağ asitleri kanda ve beyinde birikir. Bu hastalıkta hangi organelin işlevi bozuktur?', 'Peroksizom', ['Ribozom', 'Golgi cisimciği', 'Sentrozom'], 'Adrenolökodistrofide çok uzun zincirli yağ asitlerinin peroksizoma taşınması bozuktur; bu yağ asitleri yıkılamaz ve sinir sisteminin miyelin kılıfına zarar verir.'),
  ('Zellweger sendromunda hücreler ya hiç peroksizom içermez ya da içi boş peroksizom kılıfları taşır. Bu hastalığın temel nedeni hangisidir?', 'Peroksizom proteinlerinin organele aktarılamaması', ['Mitokondri DNA\'sında mutasyon', 'Lizozomların asitleşememesi', 'Ribozomların ER\'ye bağlanamaması'], 'Zellweger sendromu peroksizom oluşumu ve protein aktarımı için gereken genlerdeki bozukluklardan kaynaklanır; enzimler organele giremediği için peroksizom işlevleri yürütülemez.'),
  ('Karaciğer hücrelerinde aşırı alkol alımında etanolün bir kısmının katalaz aracılığıyla asetaldehite çevrildiği organel hangisidir?', 'Peroksizom', ['Golgi cisimciği', 'Çekirdek', 'Ribozom'], 'Katalaz H₂O₂\'yi kullanarak etanol gibi bazı maddeleri de yükseltgeyebilir; karaciğer ve böbrek hücrelerindeki peroksizomlar bu yolla detoksifikasyona katkı yapar.'),
  ('Bir paramesyuma ATP üretimini engelleyen bir madde verildiğinde, tatlı suda bir süre sonra hücrenin şişip patladığı görülüyor. Bu gözlem kontraktil koful hakkında neyi gösterir?', 'Suyu dışarı atmak için enerji harcadığını', ['Kofulun su almayı tamamen durdurduğunu', 'Kofulun yalnız tuz biriktirdiğini', 'Hücre zarının suya geçirimsiz olduğunu'], 'Kontraktil koful, osmozla sürekli giren suyu toplayıp enerji harcayarak dışarı pompalar. Enerji kesilince su atılamaz ve hücre patlar.'),
  ('Bazı siyanobakteriler protein duvarlı içi gaz dolu keseciklerin sayısını değiştirerek suda yüzebilir ya da batabilir. Bu yapıların sağladığı başlıca yarar nedir?', 'Fotosentez için uygun ışık derinliğine yerleşmek', ['Hücreye besin olarak oksijen depolamak', 'Hücreyi saldırganlardan zehirle korumak', 'DNA\'yı çekirdek gibi çevreleyip korumak'], 'Gaz kofulları (gaz kesecikleri) hücrenin yoğunluğunu düşürür; hücreler sayılarını ayarlayarak su sütununda ışığın uygun olduğu derinliğe yükselip alçalabilir.'),
  ('Mitokondrinin dış ve iç zarları geçirgenlik bakımından karşılaştırıldığında hangisi doğrudur?', 'Dış zar geçirgen, iç zar seçicidir', ['İç zar her şeyi geçirir, dış zar hiçbir şeyi geçirmez', 'İki zar da aynı geçirgenliktedir ve bütün iyonları serbestçe geçirir', 'Dış zar yalnız protonları geçirir'], 'Dış zardaki porinler küçük moleküllerin serbest geçişine izin verir. İç zar ise iyonlara ve protonlara karşı çok seçicidir; madde geçişi özel taşıyıcılarla olur.'),
  ('İnsan mitokondri DNA\'sı için hangisi doğrudur?', 'Halkasal, yaklaşık 16 500 baz çifti', ['Doğrusal yapıda ve milyonlarca baz çifti uzunluğundadır', 'Histon proteinlerine sarılı 23 kromozomdan oluşur', 'Yalnızca RNA\'dan oluşur ve hiç gen taşımaz'], 'İnsan mitokondri DNA\'sı yaklaşık 16 569 baz çiftlik halkasal bir moleküldür ve 37 gen taşır; bu yapısı bakteri kromozomuna benzer.'),
  ('Canlı hücrelerde floresanla işaretlenmiş mitokondriler izlendiğinde sürekli birleşip ayrıldıkları, ağ benzeri yapılar oluşturdukları görülür. Bu kaynaşma ve bölünme dengesinin hücreye yararlarından biri nedir?', 'Hasarlı kısımların ayıklanabilmesi', ['Mitokondrilerin çekirdeğe dönüşebilmesi', 'Hücre zarının kalınlaşması', 'ATP\'nin artık mitokondri dışında, sitoplazmada üretilebilmesi'], 'Kaynaşma mitokondriler arasında içerik paylaşımını sağlar; bölünme ise hasarlı bölümlerin ayrılıp mitofajiyle yıkılmasına olanak tanır.'),
  ('Programlı hücre ölümünün (apoptoz) başlamasında mitokondrinin iki zarı arasındaki boşluktan sitoplazmaya salınan hangi protein önemli bir tetikleyicidir?', 'Sitokrom c', ['Hemoglobin', 'Aktin', 'Tübülin dimeri'], 'Normalde solunum zincirinde elektron taşıyan sitokrom c, mitokondri dış zarı geçirgenleşince sitoplazmaya çıkar ve kaspaz enzimlerini etkinleştirerek apoptozu başlatır.'),
  ('Mitokondri iç zarının protein oranı hücre zarına göre nasıldır ve bunun nedeni nedir?', 'Çok yüksektir; solunum proteinleriyle doludur', ['Çok daha düşüktür; neredeyse yalnız lipitten oluşur', 'Eşittir; bütün zarların bileşimi aynıdır', 'Hiç protein içermez; geçişler difüzyonla olur'], 'İç zar kütlece büyük ölçüde proteindir; elektron taşıma kompleksleri, ATP sentaz ve çeşitli taşıyıcılar bu zarı en protein zengin zarlardan biri yapar.'),
  ('Kloroplast kaç ayrı zar sistemi içerir ve bunlar hangileridir?', 'Üç: dış zar, iç zar ve tilakoit zarı', ['İki: yalnız dış ve iç zar', 'Bir: yalnız tilakoit zarı', 'Dört: dış zar, iç zar, krista ve tonoplast'], 'Kloroplastta iki zarlı zarfın yanı sıra stroma içinde ayrı bir tilakoit zar sistemi bulunur; bu yüzden zarlar arası boşluk, stroma ve tilakoit içi olmak üzere üç bölme oluşur.'),
  ('Spirogira adlı ipliksi yeşil algin hücrelerinde kloroplastın biçimi hangisidir?', 'Hücre boyunca sarmal şeritler', ['Çok sayıda küçük yuvarlak disk', 'Tek bir yıldız biçimli yapı', 'Halka biçimli tek bir bant'], 'Spirogira, adını hücre çeperinin hemen altında sarmal biçimde kıvrılan şerit kloroplastlarından alır.'),
  ('Güçlü ışık altında yaprak hücrelerindeki kloroplastların hücre çeperlerinin ışığa paralel yüzlerine çekildiği, zayıf ışıkta ise ışığa dik yüzlere yayıldığı görülür. Bu hareketlerin uyumsal anlamı nedir?', 'Işık soğurmayı koşula göre ayarlamak', ['Hücre bölünmesini hızlandırmak', 'Kloroplastları merkezi kofula taşıyıp orada sindirmek', 'Hücreye su girişini durdurmak'], 'Kloroplastlar aktin iplikleri boyunca hareket ederek güçlü ışıkta kendilerini gölgeler, zayıf ışıkta ise ışık alan yüzeyi en büyük olacak biçimde dizilir.'),
  ('Bitkilerde bütün plastit türlerinin köken aldığı, bölünen meristem hücrelerinde bulunan küçük ve farklılaşmamış plastitlere ne ad verilir?', 'Proplastit', ['Kromoplast', 'Amiloplast', 'Etioplast'], 'Proplastitler hücrenin bulunduğu dokuya ve ışık koşuluna göre kloroplast, kromoplast, lökoplast gibi farklı plastitlere dönüşür.'),
  ('Karanlıkta çimlenen fidelerin yaprak hücrelerinde, klorofil içermeyen ve içinde düzenli bir zar örgüsü taşıyan plastitler bulunur; fide ışığa çıkınca bunlar kısa sürede kloroplasta dönüşür. Bu plastitlere ne ad verilir?', 'Etioplast', ['Kromoplast', 'Amiloplast', 'Elayoplast'], 'Etioplastlar ışıksızlıkta kloroplast gelişiminin durduğu evredeki plastitlerdir; ışık klorofil sentezini başlatınca tilakoitler hızla kurulur.'),
  ('Kök şapkasındaki bazı hücrelerde bulunan, ağır nişasta taneleriyle dolu olduğu için yerçekimi yönünde çöken ve kökün aşağı doğru büyüme yönünü algılamasına yardım eden plastitler hangileridir?', 'Amiloplastlar', ['Kloroplastlar', 'Kromoplastlar', 'Etioplastlar'], 'Kök şapkasındaki statolit işlevli amiloplastlar hücrenin alt kısmına çöker; bu konum bilgisi kökün yerçekimine yönelimli büyümesini başlatan sinyalleri tetikler.'),
  ('Aşağıdaki bulgulardan hangisi mitokondri ve kloroplastın bakteri kökenli olduğu görüşünü desteklemez?', 'Çekirdek zarıyla çevrili olmaları', ['Bakterilerdekine benzeyen 70S tipi ribozomlara sahip olmaları', 'Histonsuz halkasal DNA taşımaları', 'Bakteriler gibi ikiye bölünerek çoğalmaları'], 'Bölünme biçimi, halkasal histonsuz DNA ve 70S benzeri ribozomlar bakterilerle ortak özelliklerdir. Organellerin çekirdek zarıyla çevrili olduğu ise doğru değildir ve bakteri kökenine kanıt sayılmaz.'),
  ('Bakteri ribozomlarını hedef alan kloramfenikol gibi bazı antibiyotiklerin yüksek dozda insan hücrelerinde de yan etki oluşturabilmesinin nedeni hangisidir?', 'Mitokondri ribozomlarının bakteri ribozomlarına benzemesi', ['İnsan sitoplazmik ribozomlarının bakterilerinkiyle aynı olması', 'Antibiyotiğin çekirdek zarını eritmesi', 'Antibiyotiğin hücre duvarını yıkması'], 'Mitokondri ribozomları bakteri ribozomlarına benzediği için bu antibiyotikler mitokondride protein sentezini de baskılayabilir; bu, organelin bakteri kökenine de işaret eder.'),
  ('DNA dizi karşılaştırmalarına göre kloroplastların en yakın akrabası olan bakteri grubu hangisidir?', 'Siyanobakteriler', ['Alfa-proteobakteriler', 'Arkeler', 'Mikoplazmalar'], 'Kloroplast DNA\'sı ve rRNA dizileri siyanobakterilerle en çok benzerliği gösterir; mitokondriler ise alfa-proteobakterilerden köken almıştır.'),
  ('Mitokondri ve kloroplast genomlarının serbest yaşayan bakterilere göre çok küçük olması endosimbiyoz kuramı çerçevesinde nasıl açıklanır?', 'Genlerin çekirdeğe göçü ya da kaybı', ['Organellerin hiçbir zaman gen taşımamış olmasıyla', 'Genlerin Golgi\'de depolanmasıyla', 'Organellerin genlerini sürekli olarak virüslerden alıp sonra kaybetmesiyle'], 'Ortak yaşam süresince organel genlerinin çoğu konak çekirdeğine göç etmiş ya da gereksiz kalınca kaybolmuştur; bu yüzden organeller birçok proteinini çekirdekten alır.'),
  ('Bazı alglerde kloroplastın iki değil üç ya da dört zarla çevrili olması hangi olayla açıklanır?', 'İkincil endosimbiyozla', ['Kloroplastın iki kez bölünmesiyle', 'Kloroplastın endoplazmik retikulumdan tomurcuklanarak oluşmasıyla', 'Hücre duvarının kloroplastı sarmasıyla'], 'İkincil endosimbiyozda bir ökaryot, kloroplast taşıyan bir algi yutar; fazladan zarlar yutulan algin zarından ve konağın kesecik zarından gelir.'),
  ('Hücre iskeletinin üç ana elemanı kalınlıklarına göre inceden kalına doğru hangi sırada dizilir?', 'Mikrofilament, ara filament, mikrotübül', ['Mikrotübül, ara filament, mikrofilament', 'Ara filament, mikrofilament, mikrotübül', 'Mikrofilament, mikrotübül, ara filament dizisi'], 'Mikrofilamentler yaklaşık 7 nm, ara filamentler yaklaşık 10 nm, mikrotübüller ise yaklaşık 25 nm çapındadır.'),
  ('Hayvan hücrelerinde mikrotübüllerin eksi uçları genellikle nerede bulunur?', 'Sentrozomda', ['Hücre zarının dış yüzünde', 'Çekirdekçikte', 'Lizozomların içinde'], 'Mikrotübüller sentrozomdan çıkar; eksi uçları sentrozomda sabitlenirken artı uçları hücrenin çevresine doğru uzanır.'),
  ('Porsuk ağacından elde edilen paklitaksel (taksol) mikrotübüllere bağlanıp onların sökülmesini engeller. Bu ilacın kanser tedavisinde kullanılmasının nedeni nedir?', 'Bölünmeyi durdurması', ['Hücre zarında delikler açması', 'DNA\'yı doğrudan kesmesi', 'Kanser hücrelerinin mitokondrisini çoğaltıp onları yorması'], 'İğ ipliklerinin işlev görmesi için mikrotübüllerin sürekli kurulup sökülmesi gerekir; taksol onları dondurduğu için hızlı bölünen hücreler bölünmeyi tamamlayamaz.'),
  ('Madagaskar cezayir menekşesinden elde edilen vinkristin ve vinblastin gibi kanser ilaçlarının hücre iskeleti üzerindeki etkisi hangisidir?', 'Mikrotübül kurulumunu engellemek', ['Aktin ipliklerini kalıcı olarak sabitlemek', 'Ara filamentleri çoğaltmak', 'Hücre zarına kolesterol eklemek'], 'Vinka alkaloitleri tübüline bağlanıp mikrotübül kurulumunu engeller; iğ oluşamadığı için bölünen hücreler durur. Taksol ise tersine mikrotübülleri aşırı kararlı hâle getirir.'),
  ('Köygöçüren mantarının (Amanita phalloides) zehirlerinden falloidin aktin ipliklerine sıkıca bağlanır. Bu özelliği nedeniyle falloidin laboratuvarda nasıl kullanılır?', 'Aktin ağını görünür kılmak için', ['Mikrotübülleri çoğaltıp hücreyi bölmek için', 'DNA\'yı boyayıp kromozom saymak için', 'Hücre zarını eritip organelleri santrifüjle ayırmak için'], 'Falloidin yalnız ipliksi aktine bağlandığından floresan işaretli falloidin, hücrelerdeki mikrofilament ağını mikroskopta göstermek için yaygın bir araçtır.'),
  ('Bağırsak hücrelerinin mikrovilluslarının dik durmasını sağlayan iç destek hangi elemandan oluşur?', 'Aktin demetlerinden', ['Dokuz çift mikrotübülden', 'Selüloz liflerinden', 'Kollajen liflerinden'], 'Her mikrovillusun içinde birbirine çapraz bağlı aktin ipliklerinden oluşan bir demet bulunur; mikrovilluslar sil gibi mikrotübül iskeleti taşımaz ve hareketli değildir.'),
  ('Hücrenin zarın hemen altında aktin ipliklerinden oluşan yoğun ağa (korteks) sahip olmasının hücreye sağladığı yarar hangisidir?', 'Zarı destekleyip biçim değişimini sağlaması', ['Hücreye kalıtsal bilgi depolaması', 'Hücre içinde ATP üretmesi', 'Hücre zarını suya karşı tamamen geçirimsiz yapması'], 'Hücre korteksi zarın altında esnek bir destek oluşturur; aktin ağının yeniden düzenlenmesiyle hücre yüzeyinde çıkıntılar, girintiler ve biçim değişiklikleri meydana gelir.'),
  ('Ara filamentleri mikrotübül ve mikrofilamentlerden ayıran özellik hangisidir?', 'Çok kararlı olup çekme kuvvetine dayanıklılık sağlamaları', ['Sürekli hızla kurulup sökülmeleri', 'Motor proteinlere yol oluşturmaları', 'Tübülin ya da aktinden yapılmaları'], 'Ara filamentler halat gibi sağlam ve kalıcı yapılardır; kutupları yoktur ve üzerlerinde motor protein yürümez. Asıl görevleri hücreye mekanik dayanıklılık vermektir.'),
  ('Basit tip epidermolizis bülloza hastalarında hafif bir sürtünme bile deride kabarcıklara yol açar. Bu hastalığın nedeni olan mutasyon hangi yapıyı etkiler?', 'Epitel hücrelerindeki keratin ara filamentlerini', ['Akyuvarların kamçılarını', 'Mitokondri DNA\'sını', 'Kas hücrelerindeki tropomiyozini'], 'Bazal epitel hücrelerinde keratin filamentleri bozuk olduğunda hücreler mekanik zorlanmaya dayanamaz ve yırtılır; bu da kabarcık oluşumuna yol açar.'),
  ('Sinir hücrelerinin uzun aksonlarına mekanik destek veren ve akson çapını belirlemeye katkı yapan ara filamentlere ne ad verilir?', 'Nörofilamentler', ['Keratin lifleri', 'Mikrovilluslar', 'Sentriyoller'], 'Nörofilamentler sinir hücrelerine özgü ara filamentlerdir; aksonun iç iskeletini oluşturarak çapını ve sağlamlığını belirler.'),
  ('Kinezin ve dinein motor proteinleri mikrotübül üzerinde hangi yönlerde yürür?', 'Kinezin artı uca, dinein eksi uca doğru', ['Kinezin eksi uca, dinein artı uca doğru', 'İkisi de yalnız artı uca doğru', 'İkisi de aktin üzerinde yürür'], 'Hücrelerin çoğunda artı uçlar çevreye baktığı için kinezin yükleri hücre merkezinden çevreye, dinein ise çevreden merkeze taşır.'),
  ('Sinir hücresinde akson ucunda kullanılmış zar keseciklerinin hücre gövdesine geri taşınmasında başlıca hangi motor protein görev yapar?', 'Dinein', ['Kinezin', 'Miyozin', 'Aktin'], 'Aksonda mikrotübüllerin artı uçları akson ucuna bakar. Gövdeye doğru, yani eksi uca doğru geri taşımayı dinein yapar.'),
  ('İnsan vücudundaki hücrelerin çoğunda tek tane bulunan, hareket etmeyen ve 9+0 düzenli mikrotübül iskeletine sahip birincil silin başlıca görevi nedir?', 'Çevredeki kimyasal ve mekanik sinyalleri algılamak', ['Hücreyi sıvı içinde yüzdürmek', 'Mukusu sürekli süpürmek', 'Hücreyi bölünme sırasında ikiye ayırmak'], 'Birincil siller anten gibi çalışır; örneğin böbrek kanalcıklarındaki hücrelerde sıvı akışını algılar. Bozuklukları polikistik böbrek gibi hastalıklarla ilişkilidir.'),
  ('Bakteri kamçısı ile ökaryot kamçısı karşılaştırıldığında hangisi doğrudur?', 'Bakteri kamçısı pervane gibi döner; mikrotübül içermez', ['İkisi de 9+2 düzenli mikrotübüllerden oluşur', 'Bakteri kamçısı dinein kollarıyla kırbaç gibi bükülür', 'Ökaryot kamçısı flagellin proteininden oluşan içi boş bir tüptür'], 'Bakteri kamçısı flagellin proteininden yapılmış katı bir ipliktir ve tabandaki bir motorla döndürülür. Ökaryot kamçısı ise 9+2 mikrotübül iskeletli ve zarla örtülüdür; dinein kollarıyla bükülür.'),
  ('Bakterilerin birbirine bağlanıp plazmit DNA\'sını bir hücreden diğerine aktarmasını sağlayan uzun protein uzantısına ne ad verilir?', 'Eşey (konjugasyon) pilusu', ['Kamçı', 'Fimbriya', 'Kapsül'], 'Konjugasyonda verici bakterinin eşey pilusu alıcıya tutunup iki hücreyi yaklaştırır; ardından plazmit DNA\'sı alıcıya geçer.'),
  ('Bakteri hücresi bölünürken ortada halka oluşturarak bölünme düzlemini belirleyen FtsZ proteini, ökaryotlardaki hangi hücre iskeleti proteinine benzer?', 'Tübülin', ['Aktin', 'Keratin', 'Lamin'], 'Bakterilerde de hücre iskeleti benzeri proteinler vardır: FtsZ tübülinin, MreB ise aktinin bakterideki akrabasıdır.'),
  ('Siyanobakterilerde fotosentez pigmentlerini taşıyan zarlar nerede bulunur?', 'Sitoplazmadaki tilakoitlerde', ['Kloroplastların içinde', 'Çekirdek zarında', 'Bakteri kamçısının tabanındaki zar halkalarında'], 'Siyanobakteriler kloroplast taşımaz; fotosentez pigmentleri sitoplazmada yer alan, hücre zarından köken alan tilakoit zarlarına yerleşmiştir.'),
  ('Bakterilerin sitoplazmasında glikojen, polifosfat ya da kükürt gibi maddelerin depolandığı, çoğu zarla çevrili olmayan taneciklere genel olarak ne ad verilir?', 'Depo taneleri', ['Lizozomlar', 'Mitokondriler', 'Golgi kesecikleri'], 'Prokaryotlar zarlı organel taşımadığından besin ve mineral fazlalarını sitoplazmada taneler hâlinde biriktirir; bunlar ihtiyaç anında kullanılır.'),
  ('Arkeler ile ökaryotlar arasındaki moleküler benzerliklerden biri hangisidir?', 'DNA\'nın histon benzeri proteinlere sarılması', ['İkisinin de zarla çevrili çekirdek taşıması', 'İkisinin de peptidoglikan çeper yapması', 'İkisinin de mitokondri içermesi'], 'Birçok arke DNA\'sını ökaryot histonlarına benzeyen proteinlerle paketler; ayrıca transkripsiyon düzenekleri de bakterilerden çok ökaryotlarınkine benzer.'),
  ('Göz merceğini oluşturan lif hücreleri gelişimleri sırasında çekirdeklerini ve organellerinin çoğunu yitirir. Bunun işlevsel yararı nedir?', 'Merceğin saydam kalması', ['Hücrelerin daha hızlı bölünmesi', 'Merceğin oksijen tüketiminin artması', 'Hücrelerin kasılabilmesi'], 'Organeller ışığı saçarak görüntüyü bozardı; olgun mercek hücreleri büyük ölçüde kristalin proteinleriyle dolu, organelsiz ve saydam yapılardır.'),
  ('Bir karaciğer hücresi incelendiğinde bol miktarda düz ER, peroksizom ve glikojen tanesi görülür. Bu donanım karaciğerin hangi görevleriyle uyumludur?', 'Detoksifikasyon ve glikoz depolama', ['Işıkla şeker üretimi', 'Kasılma ve hareket', 'Sinyal iletimi ve uzun süreli bellek oluşturma'], 'Düz ER ve peroksizomlar ilaç, alkol gibi maddeleri etkisizleştirir; glikojen taneleri kan şekerinin düzenlenmesinde kullanılan glikoz deposudur.'),
  ('Suda tamamen iyonlarına ayrışan 0,1 M CaCl₂ çözeltisi ile 0,25 M glikoz çözeltisi yalnız suyu geçiren bir zarla ayrılıyor. Su net olarak hangi yöne geçer?', 'Glikoz tarafından CaCl₂ tarafına', ['CaCl₂ tarafından glikoz tarafına', 'Hiçbir yöne geçmez', 'Önce glikoz tarafına, sonra eşit olarak iki yöne'], 'CaCl₂ bir Ca²⁺ ve iki Cl⁻ verir; 0,1 M × 3 = 0,3 osmol/L tanecik oluşur. Bu değer glikozun 0,25 osmol/L\'sinden büyük olduğundan su CaCl₂ tarafına geçer.'),
  ('Bir molekülün 10 µm\'lik bir hücreyi difüzyonla geçmesi yaklaşık 0,1 saniye sürüyorsa, aynı molekülün yalnız difüzyonla 1 mm yol alması yaklaşık kaç saniye sürer?', '1000 saniye', ['10 saniye', '100 000 saniye', '0,2 saniye'], 'Süre uzaklığın karesiyle artar. 1 mm, 10 µm\'nin 100 katıdır; süre 100² = 10 000 kat uzar: 0,1 × 10 000 = 1000 saniye (yaklaşık 17 dakika).'),
  ('Çözünen potansiyeli −0,6 MPa olan bir bitki hücresi saf suya konuyor. Hücre suyla dengeye geldiğinde basınç potansiyeli kaç olur? (Hacim değişimini ihmal ediniz.)', '+0,6 MPa', ['0 MPa', '+0,30 MPa', '+1,2 MPa'], 'Saf suyun potansiyeli 0\'dır. Dengede hücrenin su potansiyeli de 0 olmalıdır: Ψ = −0,6 + Ψp = 0, buradan Ψp = +0,6 MPa bulunur.'),
  ('Tam plazmoliz geçirmiş bir hücrede basınç potansiyeli sıfır, çözünen potansiyeli ise −0,9 MPa\'dır. Bu hücre su potansiyeli −0,7 MPa olan bir çözeltiye aktarılırsa ilk olarak ne olur?', 'Hücre su alır ve deplazmoliz başlar', ['Hücre su kaybetmeyi sürdürür', 'Su alışverişi hiç olmaz', 'Hücre hemen patlar'], 'Hücrenin su potansiyeli Ψ = −0,9 + 0 = −0,9 MPa\'dır ve çözeltininkinden (−0,7) düşüktür. Su yüksek potansiyelden düşüğe, yani çözeltiden hücreye geçer.'),
  ('Bir hücrenin içinde K⁺ derişimi 140 mM, dışında 5 mM\'dir. Zarda yalnız K⁺ kanalları açıldığında K⁺ iyonlarının hareketi için hangisi beklenir?', 'Dışarı çıkar ve içeriyi negatifleştirir', ['Derişim farkına karşı ATP harcanmadan içeri girer ve birikir', 'Hiç hareket etmez', 'Dışarı çıkar ve içerisi pozitifleşir'], 'K⁺ derişim farkı yönünde dışarı akar. Her çıkan pozitif yük hücre içini biraz daha negatif yapar; oluşan elektrik çekimi bir süre sonra K⁺ çıkışını dengeler.'),
  ('Bir hücre ürettiği ATP\'nin yaklaşık dörtte birini Na⁺/K⁺ pompası için harcıyor ve saniyede 4 × 10⁹ ATP üretiyorsa, pompalar saniyede kaç Na⁺ iyonu dışarı atar?', '3 × 10⁹', ['1 × 10⁹', '12 × 10⁹', '2 × 10⁹'], 'Pompalara 4 × 10⁹ / 4 = 1 × 10⁹ ATP gider; her ATP için 3 Na⁺ atılır: 3 × 10⁹ Na⁺.'),
  ('Kırmızı pancar kökü dilimleri farklı sıcaklıklarda suda bekletildiğinde, 60 °C ve üzerinde suyun hızla kırmızıya boyandığı görülüyor. Bunun en doğru açıklaması nedir?', 'Sıcaklığın zarları bozması', ['Sıcaklığın pigmenti suda daha az çözünür yapması', 'Pigmentin yüksek sıcaklıkta hızla yeniden sentezlenip dışarı salgılanması', 'Hücre duvarının sıcakta kalınlaşması'], 'Kırmızı pigment kofulda, iki zarın arkasında tutulur. Yüksek sıcaklık zar proteinlerini bozup lipitleri aşırı akışkan hâle getirdiğinde zarlar geçirgenleşir ve pigment dışarı sızar.'),
  ('Bazı bakterilerin salgıladığı toksinler hedef hücrenin zarına yerleşip halka biçimli kanallar oluşturur. Bu toksinler hücreyi en doğrudan nasıl öldürür?', 'Zarın seçici geçirgenliğini yok ederek', ['Hücrenin DNA\'sını kopyalayarak', 'Hücreye fazladan ATP vererek', 'Hücre zarını kalınlaştırıp madde alışverişini tamamen keserek'], 'Gözenek oluşturan toksinler zarın seçici geçirgenliğini yok eder; iyonlar ve su serbestçe akınca hücre osmotik dengesini yitirir ve parçalanır.'),
  ('Kolera toksini bağırsak hücrelerinde cAMP düzeyini sürekli yüksek tutar ve sonuçta zardaki klorür kanallarını açık bırakır. Bu durum neden şiddetli ishale yol açar?', 'Cl⁻ ile birlikte Na⁺ ve suyun boşluğa geçmesi', ['Toksinin bağırsak hücrelerini sindirmesi', 'Bağırsakta suyun emiliminin aktif olarak artması', 'Klorürün hücre içinde birikip suyu içeri çekmesi'], 'Açık kalan klorür kanallarından bağırsak boşluğuna Cl⁻ çıkar; elektriksel denge için Na⁺, osmotik denge için su da boşluğa geçer ve büyük hacimde sulu dışkı oluşur.'),
  ('Kalıtsal sferositozda alyuvar zarının altındaki iskelet ağını oluşturan proteinler (örneğin spektrin) bozuktur. Bu hastalarda alyuvarlar nasıl etkilenir?', 'Küreleşip kırılganlaşır', ['Daha esnek hâle gelip daha uzun yaşar', 'Çekirdek kazanıp bölünmeye başlar', 'Mitokondri sayısı artar'], 'Zar iskeleti alyuvara disk biçimini ve esnekliğini verir. Bu iskelet bozulunca hücreler küreleşir, dar kılcallardan geçemez ve dalakta erken yıkılır.'),
  ('Doğumdan itibaren glikoz ve galaktoz içeren besinlerle ağır ishal görülen bir bebekte, fruktoz içeren besinler sorun yaratmıyor. Bu bulgu en çok hangi bozuklukla uyumludur?', 'Na⁺ bağımlı şeker taşıyıcısının bozukluğu', ['Mide asidinin yetersizliği', 'Fruktoz taşıyıcısının fazla çalışıp diğer şekerleri engellemesi', 'Bağırsakta lizozomların bulunmaması'], 'Glikoz ve galaktoz aynı Na⁺ bağımlı ortak taşıyıcıyla emilir; bu taşıyıcı bozuksa iki şeker bağırsakta kalır ve suyu çekerek ishal yapar. Fruktoz başka bir taşıyıcıyla emildiği için sorun çıkarmaz.'),
  ('Hücreler dondurulurken en büyük hasar hücre içinde oluşan buz kristallerinin zarları yırtmasından kaynaklanır. Sperm, embriyo ve kök hücre saklamada ortama gliserol gibi maddeler eklenmesinin amacı nedir?', 'Hücre içinde buz kristali oluşumunu azaltmak', ['Hücrelerin dondurulurken bölünmesini sağlamak', 'Hücre zarını kalıcı olarak sertleştirmek', 'Hücrelere besin olarak enerji vermek'], 'Gliserol ve DMSO gibi dondurma koruyucular suyun donma davranışını değiştirir; büyük buz kristallerinin oluşmasını önleyerek zarların zarar görmesini azaltır.'),
  ('Bitki virüslerinin çoğu, ürettikleri "hareket proteinleri" sayesinde bir hücreden komşusuna yayılır. Bu proteinlerin etkilediği yapı hangisidir?', 'Plazmodezmalar', ['Stomalar', 'Lentiseller', 'Kök tüylerinin uçları'], 'Hareket proteinleri plazmodezmaların geçiş açıklığını genişleterek virüs genomunun komşu hücreye geçmesini sağlar; böylece enfeksiyon simplast yoluyla yayılır.'),
  ('Lizozom ve peroksizom karşılaştırıldığında hangisi doğrudur?', 'Lizozomda hidrolitik enzimler, peroksizomda oksidaz ve katalaz bulunur', ['İkisi de çift zarlı ve DNA taşıyan organellerdir', 'Lizozomlar H₂O₂ üretip parçalar', 'Peroksizom enzimleri Golgi\'de işaretlenip gelir'], 'Lizozomlar asidik ortamda büyük molekülleri hidrolizle sindirir. Peroksizomlar ise oksidasyon tepkimeleri yapar ve oluşan H₂O₂\'yi katalazla yok eder.'),
  ('Hücreye reseptör aracılı endositozla alınan LDL parçacığındaki kolesterolün hücre tarafından kullanılabilir hâle gelmesi hangi sırayla olur?', 'Endozom → lizozom → kolesterol sitoplazmaya geçer', ['Golgi → çekirdek → kolesterol DNA\'ya bağlanır', 'Mitokondri → kloroplast → kolesterol nişastaya dönüşür', 'Ribozom → ER → kolesterol salgılanır'], 'Kesecik önce endozoma ulaşır, reseptör zara geri döner; LDL lizozomda sindirilir ve serbest kalan kolesterol zar yapımında kullanılmak üzere sitoplazmaya geçer.'),
  ('2014 Nobel Kimya Ödülü\'nün verildiği "süper çözünürlüklü floresan mikroskopisi" hangi engeli aşmayı sağlamıştır?', 'Işık mikroskobunun yaklaşık 0,2 µm\'lik ayırma sınırını', ['Elektron mikroskobunda örneğin vakuma konma zorunluluğunu', 'Mikroskopta renkli görüntü elde edilememesini', 'Canlı hücrelerin hiç boyanamamasını'], 'Betzig, Hell ve Moerner\'in geliştirdiği yöntemler floresan moleküllerin denetimli yanıp sönmesinden yararlanarak ışığın kırınım sınırının altındaki yapıları ayırt etmeyi sağlamıştır.'),
  ('Elektron mikroskobu preparatlarının kurşun ve uranyum gibi ağır metal tuzlarıyla boyanmasının nedeni nedir?', 'Elektronları saçıp yapılar arasında karşıtlık oluşturmak', ['Örneğe renk kazandırıp renkli görüntü almak', 'Örneği canlı tutmak', 'Elektron demetini hızlandırmak'], 'Biyolojik moleküller elektronları zayıf saçar. Ağır metal atomları elektronları güçlü saçtığı için bağlandıkları yapılar görüntüde koyu görünür.'),
  ('Kenarları 2 cm olan küp biçimli, fenolftaleinli bir agar bloğu sodyum hidroksit çözeltisine bırakılıyor ve baz 10 dakikada her yüzeyden 0,5 cm içeri işliyor. Bu sürede bloğun hacminin yüzde kaçı pembeye boyanmış olur?', '%87,5', ['%50', '%25', '%12,5'], 'İçeride boyanmamış kalan küpün kenarı 2 − 2 × 0,5 = 1 cm, hacmi 1 cm³\'tür. Toplam hacim 8 cm³ olduğundan boyanan kısım (8 − 1) / 8 = %87,5\'tir.'),
  ('Fenolftaleinli agar küpleriyle yapılan difüzyon deneyinde aynı sürede küçük küplerin büyük küplere göre hacimce daha büyük oranda renk değiştirmesi hücreler için neyi modeller?', 'Küçük hücrede maddenin her yere çabuk ulaşmasını', ['Büyük hücrelerin birim zamanda hacimlerine oranla daha fazla madde aldığını', 'Difüzyonun yalnız büyük hücrelerde olduğunu', 'Hücre büyüklüğünün madde alışverişini etkilemediğini'], 'Küçük küplerin yüzey/hacim oranı büyüktür ve merkezleri yüzeye yakındır; bu yüzden difüzyon hacmin büyük kısmına kısa sürede ulaşır. Hücrelerin küçük kalmasının bir nedeni budur.'),
  ('Bir ışık mikroskobunda görüntü 1000 kattan sonra daha da büyütüldüğünde yeni hiçbir ayrıntı görülmeyip yalnız bulanık bir görüntü elde edilmesinin nedeni nedir?', 'Ayırma gücü sınırına ulaşılmış olması', ['Preparatın bu büyütmede kuruması', 'Mikroskobun ışık kaynağının zayıflaması', 'Hücrelerin büyütme arttıkça küçülmesi'], 'Büyütme görüntüyü büyütür ama ayırma gücü (iki noktayı ayrı görebilme) ışığın dalga boyuyla sınırlıdır. Bu sınır aşıldığında büyütmeyi artırmak yalnızca "boş büyütme" sağlar.'),
  ('Çiçekli bitki hücrelerinde sentrozom ve sentriyol bulunmamasına karşın mikrotübüller nasıl düzenlenir?', 'Dağınık çekirdeklenme merkezlerinden', ['Hiç mikrotübül oluşmaz, görevi aktin iplikleri üstlenir', 'Mikrotübüller hücre duvarında kurulur', 'Mikrotübüller yalnız kloroplastın içinde kurulur'], 'Bitki hücrelerinde mikrotübül çekirdeklenmesi çekirdek zarının yüzeyi ve zar altındaki çok sayıda dağınık merkezde olur; bu da hücre iskeletinin sentriyolsüz kurulabileceğini gösterir.'),
  ('Glikoz hücreye kolaylaştırılmış difüzyonla girer girmez fosfat eklenerek glikoz-6-fosfata dönüştürülür. Bunun glikoz alımına etkisi nedir?', 'Serbest glikozu düşük tutup girişi sürdürür', ['Glikozun hücreden hızla geri çıkmasını sağlar', 'Taşıyıcının ATP harcamasını gerektirir', 'Glikoz alımını tamamen durdurur'], 'Fosfatlı glikoz taşıyıcıya uymaz ve hücreden çıkamaz; içerideki serbest glikoz düşük kaldığı için derişim farkı korunur ve glikoz girişi sürer.'),
  ('Hint yağı bitkisinin tohumlarında bulunan risin adlı zehir hücreye endositozla girdikten sonra ribozomların büyük alt birimindeki rRNA\'yı bozar. Bu zehrin hücreyi öldürme biçimi nedir?', 'Protein sentezini durdurması', ['Hücre zarında delik açması', 'DNA eşlenmesini hızlandırması', 'Mitokondride ATP üretimini artırması'], 'Risin rRNA\'dan bir baz kopararak ribozomu işlevsiz kılar; tek bir risin molekülü binlerce ribozomu bozabildiği için çok düşük dozda bile öldürücüdür.'),
  ('Sıtma tedavisinde kullanılan klorokin gibi zayıf bazik maddeler asidik bölmelerde birikerek oradaki pH\'ı yükseltir. Bu maddeler hücrede en çok hangi organelin işlevini etkiler?', 'Lizozom', ['Ribozom', 'Çekirdekçik', 'Sentrozom'], 'Zayıf bazlar yüksüz hâlde zardan geçer, asidik lizozomda proton alıp yüklenince dışarı çıkamaz ve birikir; pH yükselince lizozom enzimleri iyi çalışamaz.'),
  ('Bağırsak epitelinde maddelerin hücrelerin içinden geçerek ve hücreler arasındaki aralıktan geçerek taşınması sırasıyla nasıl adlandırılır?', 'Transselüler ve paraselüler yol', ['Hücreler arası ve hücre içi yol', 'Endositoz ve ekzositoz', 'Fagositoz ve pinositoz'], 'Transselüler yolda madde iki zardan geçer; paraselüler yolda ise hücrelerin arasından ilerler ve bu geçiş sıkı bağlantıların sıkılığıyla sınırlanır.'),
  ('Bir hormona sürekli ve yüksek düzeyde maruz kalan hücrelerin zarlarındaki reseptör sayısının zamanla azaldığı görülür. Bu azalmanın en olası mekanizması nedir?', 'Reseptörlerin endositozla içeri alınması', ['Reseptörlerin hücre dışına salgılanması', 'Reseptör genlerinin kalıcı olarak silinmesi', 'Zarın kalınlaşıp reseptörleri örtmesi'], 'Hormona bağlı reseptörler endositozla içeri alınır; bir kısmı lizozomlarda yıkılır. Böylece hücre uyarana duyarlılığını azaltır.'),
  ('Bir sinyal molekülü bağlandığında doğrudan açılarak iyon geçişine izin veren reseptörler, sinyali hücre içine iletmede diğer reseptör türlerine göre nasıl bir üstünlük sağlar?', 'Yanıt milisaniyeler içinde başlar', ['Yanıt günler sürer', 'Hücre içinde gen ifadesini doğrudan değiştirir', 'ATP harcamadan protein üretir'], 'İyon kanalı reseptörleri ara basamak gerektirmeden iyon akışını başlattığı için en hızlı yanıtı verir; bu yüzden hızlı sinyal iletimi gereken yerlerde yaygındır.'),
  ('Endoplazmik retikulumun iç boşluğu için hangisi doğrudur?', 'Kesintisiz tek bir bölme oluşturur', ['Her ER kesesi birbirinden bağımsız ayrı bir bölmedir', 'Sitozolle doğrudan aynı sıvıyı paylaşır', 'Yalnız çekirdek bölünürken oluşur'], 'ER zarları birbirine bağlı bir ağ oluşturur ve iç boşluk (lümen) tek ve kesintisiz bir bölmedir; bu boşluk çekirdek zarının iki katmanı arasındaki boşlukla da birleşir.'),
  ('Sinyal tanıma parçacığı (SRP) üretemeyen bir hücrede normalde salgılanması gereken bir proteinin akıbeti ne olur?', 'Sitozolde sentezlenir ve salgılanamaz', ['Doğrudan çekirdeğe taşınır', 'Normal biçimde salgılanmaya devam eder', 'Mitokondri matriksine girer'], 'SRP olmadan ribozom ER\'ye yönlendirilemez; protein sitozolde serbest ribozomlarda tamamlanır ve salgı yoluna giremez.'),
  ('Bir sinir hücresinde kinezin motor proteini işlevsiz hâle gelirse aşağıdakilerden hangisi beklenir?', 'Gövdede yapılan keseciklerin akson ucuna ulaşamaması', ['Akson ucundaki keseciklerin gövdeye dönmesinin hızlanması', 'Çekirdek zarının dağılması', 'Mitokondrilerin bölünmeyi durdurması'], 'Kinezin yükleri mikrotübüllerin artı ucuna, yani akson ucuna taşır. Kinezin bozulunca gövdede üretilen kesecik ve organeller sinaps bölgesine ulaşamaz.'),
  ('Bölünmeyen bir hayvan hücresine mikrotübülleri söken bir ilaç uygulandığında Golgi cisimciğinin çekirdek yanındaki toplu yapısını yitirip sitoplazmaya dağıldığı görülüyor. Bu gözlem neyi gösterir?', 'Golgi\'nin yerinin mikrotübüllere bağlılığını', ['Golgi\'nin mikrotübüllerden yapıldığını', 'Mikrotübüllerin yalnızca hücre bölünmesi sırasında görev aldığını', 'Golgi\'nin kendi DNA\'sı olduğunu'], 'Golgi yığınları dinein motorlarıyla mikrotübüllerin eksi uçlarına, yani sentrozom çevresine çekilir. Mikrotübüller sökülünce bu düzen bozulur; organellerin yerleşimi hücre iskeletine bağlıdır.'),
  ('Akuaporinleri ilaçla tıkanan alyuvarlar saf suya konduğunda, normal alyuvarlarla karşılaştırıldığında ne beklenir?', 'Daha yavaş şişip patlarlar', ['Hiç su almazlar ve sonsuza dek sağlam kalırlar', 'Daha hızlı şişip patlarlar', 'Su kaybederek büzülürler'], 'Su lipit çift katmanından da bir miktar geçebildiği için osmoz durmaz, yalnız yavaşlar. Akuaporinler suyun geçişini çok hızlandıran kanallardır.'),
  ('Kas dışındaki pek çok hücrede ER zarındaki Ca²⁺ pompalarının engellenmesi sitozolde hangi değişikliğe yol açar?', 'Ca²⁺ derişiminin yükselmesi', ['Ca²⁺ derişiminin sıfıra inmesi', 'Na⁺ derişiminin ER\'de artması', 'Glikoz derişiminin düşmesi'], 'Bu pompalar Ca²⁺\'u sitozolden ER içine taşır. Engellendiklerinde ER\'den sızan Ca²⁺ geri alınamaz ve sitozolde birikerek pek çok sinyal yolunu uyarır.'),
  ('Aynı hücre kültürü 37 °C\'de ve 4 °C\'de floresan işaretli bir proteinle bekletildiğinde, proteinin yalnız 37 °C\'deki hücrelerin içine kesecikler hâlinde alındığı görülüyor. Bunun en uygun açıklaması nedir?', 'Soğukta zarın ve enzimlerin yavaşlaması', ['Proteinin 4 °C\'de zara hiç değmemesi', 'Soğukta zarın tamamen geçirgen olup proteinin sızarak girmesi', '4 °C\'de ribozomların proteini yıkması'], 'Endositoz zarın bükülüp kopmasını ve enerji harcayan protein düzeneklerini gerektirir. Soğukta zar katılaşır, enzim etkinlikleri düşer ve kesecik oluşumu durur.'),
  ('Hücre duvarı sentezini engelleyen bir maddeyle muamele edilen ve hızla büyüyen bitki hücreleri saf suya konduğunda ne beklenir?', 'Zayıf bölgelerden yırtılmaları', ['Plazmoliz geçirmeleri', 'Hiç su almamaları', 'Duvarsız kalan hücrelerin fotosentezlerini artırıp büyümeleri'], 'Büyüyen hücrelerde duvar sürekli yenilenir. Sentez durunca duvar zayıflar ve turgor basıncına dayanamayan hücreler hipotonik ortamda patlar.'),
  ('Bir hücrede mitokondri iç zarındaki ATP-ADP değiştirici taşıyıcı engellenirse ne olur?', 'Yapılan ATP sitozole çıkamaz', ['Mitokondri hiç ATP üretemez hâle gelir', 'Sitozoldeki ATP mitokondriye hızla dolup orada birikir', 'Hücre zarından ATP salınır'], 'İç zar ATP\'yi geçirmez; mitokondride üretilen ATP ancak bu antiport taşıyıcıyla, sitozoldeki ADP karşılığında dışarı verilir. Taşıyıcı engellenince hücre enerji sıkıntısına düşer.'),
  ('Bir öğrenci "Bitki hücrelerinin sert bir duvarı olduğu için endositoz yapamazlar" diyor. Bu ifade için hangisi doğrudur?', 'Yanlıştır; endositoz yapabilirler', ['Doğrudur; bitki hücrelerinde hiç kesecik oluşmaz', 'Doğrudur; bitkiler yalnız ekzositoz yapar', 'Yanlıştır; bitki hücrelerinin duvarı yoktur'], 'Hücre duvarı büyük parçacıkların fagositozunu engeller; ancak bitki hücreleri zar proteinlerini ve küçük molekülleri klatrin kaplı keseciklerle içeri alabilir.'),
  ('Bir öğrenci "Peroksizomlar lizozomların özel bir türüdür" diyor. Bu ifadeyi çürüten bilgi hangisidir?', 'Enzimleri ve köken yolları farklıdır', ['İkisi de tek zarlıdır', 'İkisi de ökaryot hücrelerde bulunur', 'İkisi de mikroskopta küçük kesecik gibi görünür'], 'Lizozom enzimleri hidrolazlardır ve Golgi yoluyla gelir. Peroksizomlar ise oksidaz ve katalaz içerir ve proteinlerini doğrudan sitoplazmadan alır. Benzer görünüm aynı tür olduklarını göstermez.'),
  ('Zar proteinlerinin zarın bir yüzünden diğer yüzüne takla atarak geçmesi neredeyse hiç gözlenmez. Bunun hücre için önemi nedir?', 'Proteinlerin yönünün korunması', ['Proteinlerin daha hızlı yıkılmasını sağlar', 'Zarın akışkanlığını tamamen ortadan kaldırır', 'Proteinlerin hücre dışına salgılanmasını ve yenilenmesini kolaylaştırır'], 'Reseptörlerin bağlanma bölgesi dışarıya, enzimlerin etkin bölgesi ise içeriye bakmalıdır. Proteinlerin zar içinde dönememesi bu yönelimin kalıcı olmasını sağlar.'),
  ('Hücre zarında lipit ve protein oranı zardan zara değişir. Bu farklılık en iyi nasıl açıklanır?', 'Protein içeriğinin işleve göre değişmesi', ['Bütün zarların aynı bileşimde olup ölçüm hatası yapılmasıyla', 'Proteinlerin yalnız bitki zarlarında bulunmasıyla', 'Lipitlerin yalnız hayvan zarlarında bulunmasıyla'], 'Zarın işlevlerinin çoğunu proteinler yürütür. Taşıma ve enerji dönüşümünün yoğun olduğu zarlar protein bakımından zengin, yalıtım işlevli zarlar ise lipitçe zengindir.'),
  ('Saf bir fosfolipit çift katmanından oluşan yapay bir zar ile gerçek bir hücre zarının su geçirgenliği karşılaştırıldığında hücre zarının çok daha geçirgen olmasının nedeni nedir?', 'Akuaporin kanallarının bulunması', ['Kolesterol bulunmaması', 'Hücre zarının tek katlı olması', 'Hücre zarında hiç fosfolipit bulunmaması'], 'Su yapay çift katmandan da yavaşça geçer; ancak akuaporin kanalları içeren zarlarda su geçişi çok daha hızlıdır.'),
  ('Kloroplastların bölünmesinde, bakterilerin bölünmesinde de görev alan FtsZ benzeri bir proteinin halka oluşturması hangi görüşü destekler?', 'Kloroplastların bakteri kökenli olduğunu', ['Kloroplastların Golgi\'den oluştuğunu', 'Kloroplastların hücre bölünmesi sırasında çekirdekten koptuğunu', 'Kloroplastların mitozla bölündüğünü'], 'Bölünme düzeneğinin bakterilerdekine benzemesi, kloroplastın endosimbiyozla içeri alınmış bir siyanobakteriden türediği görüşünü destekleyen kanıtlardan biridir.'),
  ('Pek çok memelide peroksizomlarda bulunan ürat oksidaz enzimi insanda işlevsizdir. Bu durumun insan sağlığı açısından olası sonucu nedir?', 'Ürik asit birikimine ve guta yatkınlık', ['Kanda hiç ürik asit bulunmaması', 'Peroksizomların hücrelerden tamamen kaybolması', 'Lizozomların asitliğini yitirmesi'], 'Ürat oksidaz ürik asidi daha kolay atılan bir maddeye çevirir. İnsanda bu enzim bulunmadığından ürik asit düzeyi diğer memelilere göre yüksektir; aşırı birikim eklemlerde kristalleşerek gut hastalığına yol açabilir.'),
  ('Kloroplastın iç zarı ile tilakoit zarı karşılaştırıldığında hangisi doğrudur?', 'Pigmentler yalnız tilakoit zarındadır', ['İkisi de klorofil taşır', 'Tilakoit zarı kloroplastın dış sınırını oluşturur', 'İç zar granumları oluşturur'], 'Kloroplast zarfının iç zarı madde alışverişini düzenler; klorofil ve ışık toplayıcı kompleksler ise stromadaki tilakoit zarına yerleşmiştir.'),
  ('Robert Hooke\'un mantar dokusundaki "hücre"leri tanımladığı ve mikroskopla yaptığı gözlemleri çizimlerle sunduğu 1665 tarihli ünlü kitabı hangisidir?', 'Micrographia', ['Principia', 'Türlerin Kökeni', 'De Humani Corporis Fabrica'], 'Hooke, Micrographia adlı eserinde pire, sinek gözü ve mantar kesitleri gibi pek çok mikroskobik yapıyı ayrıntılı çizimlerle tanıtmıştır.'),
  ('Biyomolekülleri çok düşük sıcaklıkta dondurarak elektron mikroskobuyla atom düzeyine yakın çözünürlükte görüntülemeyi sağlayan yöntem 2017 Nobel Kimya Ödülü\'ne konu olmuştur. Bu yöntemin adı nedir?', 'Kriyo-elektron mikroskopisi', ['Faz kontrastlı floresan mikroskopisi', 'Stereo mikroskopi', 'Gram boyama'], 'Kriyo-elektron mikroskopisinde örnekler buz kristali oluşmadan camsı buz içinde dondurulur; böylece proteinler doğal biçimlerine yakın hâlde görüntülenebilir.'),
  ('Prokaryot hücrelerin besinleri endositozla alamamasının en temel nedeni hangisidir?', 'İç zar sistemi ve gerekli iskeletin yokluğu', ['Hücre zarlarının hiç bulunmaması', 'Ribozomlarının bulunmaması', 'DNA\'larının çekirdekte olması'], 'Endositoz zarın bükülüp kesecik oluşturmasını, bu keseciklerin işlenmesini ve hücre iskeletinin desteğini gerektirir; prokaryotlarda bu düzenekler yoktur, besinler zar taşıyıcılarıyla alınır.'),
  ('Fosil kayıtlarına göre ilk prokaryot hücreler ile ilk ökaryot hücreler yaklaşık ne zaman ortaya çıkmıştır?', 'Prokaryot ~3,5; ökaryot ~2 milyar yıl önce', ['İkisi aynı anda, yaklaşık 500 milyon yıl önce', 'Ökaryotlar yaklaşık 3,5 milyar, prokaryotlar yaklaşık 2 milyar yıl önce', 'Prokaryotlar 65 milyon, ökaryotlar 10 milyon yıl önce'], 'En eski prokaryot izleri yaklaşık 3,5 milyar yıllık kayaçlarda bulunur. Ökaryot hücrelere ait güvenilir fosiller ise yaklaşık 1,8–2 milyar yıl öncesine uzanır.'),
  ('Ökaryot hücrelerin prokaryotlardan çok daha büyük olabilmesine katkı yapan özelliklerden biri hangisidir?', 'Bölmelere ayrılmaları ve iç taşıma yapabilmeleri', ['Hücre zarı taşımamaları', 'Ribozom içermemeleri', 'Yalnız difüzyonla madde taşıyıp hiçbir motor protein kullanmamaları'], 'Zarlı bölmeler tepkimeleri yoğunlaştırır, iç zarlar yüzeyi artırır ve motor proteinler maddeleri uzak mesafelere taşır; böylece büyük hacimde de verimli çalışabilirler.'),
  ('Ökaryot hücrelerde zarla ayrılmış bölmelerin varlığının dezavantajlarından biri hangisidir?', 'Bölmeler arası taşımanın ek enerji gerektirmesi', ['Tepkimelerin birbirine karışması', 'Zararlı enzimlerin sitoplazmaya yayılması', 'Hücrenin büyüyememesi'], 'Bölmeleşme tepkimeleri ayırma yararı sağlar; ancak organeller arasında madde akışı için kesecikler, taşıyıcılar ve hedefleme sistemleri gerekir, bu da ek enerji maliyeti doğurur.'),
  ('Maya hücrelerinde bulunup bitki hücrelerinde bulunmayan yapı aşağıdakilerden hangisidir?', 'Kitinli hücre duvarı', ['Kloroplast', 'Selüloz ve pektinden yapılmış hücre duvarı', 'Mitokondri'], 'Maya bir mantardır; hücre duvarı selüloz yerine kitin ve glukanlardan oluşur, kloroplast taşımaz. Mitokondri ise hem bitkilerde hem mayalarda bulunur.'),
  ('Alyuvarlar hipotonik bir çözeltide patlatılıp hemoglobinleri yıkandıktan sonra geriye kalan boş zar kılıflarına "alyuvar hayaleti" denir. Bu yapılar araştırmalarda hangi amaçla kullanılmıştır?', 'Saf hücre zarının bileşimini incelemek', ['Çekirdek DNA\'sını elde etmek', 'Mitokondri iç zarındaki solunum enzimlerini ayrıntılı incelemek', 'Ribozom alt birimlerini ayırmak'], 'Memeli alyuvarlarında iç zar ve çekirdek bulunmadığından hayaletler neredeyse yalnız hücre zarından oluşur; bu da zar lipit ve proteinlerinin incelenmesi için ideal bir modeldir.'),
  ('Zar boyunca pompalarla oluşturulan iyon derişim farkları sıklıkla bir pile (bataryaya) benzetilir. Bu benzetmenin dayanağı nedir?', 'Birikmiş enerjinin iş yapmada kullanılması', ['İyonların hücrede elektrik üretip ışık saçması', 'İyonların kimyasal olarak parçalanıp doğrudan ATP molekülüne dönüşmesi', 'Zarın içinin metal iyonlarından yapılması'], 'Pompalar enerji harcayarak iyon farkı biriktirir; iyonlar fark yönünde geri akarken bu birikmiş enerji ikincil taşıma, hareket ya da ATP sentezi gibi işlerde kullanılır.'),
  ('Kuraklık ya da tuzluluğa maruz kalan bazı bitkilerin hücrelerinde prolin gibi zararsız maddelerin yüksek derişimde biriktirilmesinin hücresel yararı nedir?', 'Su potansiyelini düşürüp su tutmak', ['Hücre duvarını eritip hücrenin daha hızlı büyümesini sağlamak', 'Fotosentezi tamamen durdurmak', 'Hücre zarını suya karşı geçirimsiz yapmak'], 'Biriken bu uyumlu çözünenler çözünen potansiyelini düşürür; böylece hücre dış ortamdan su almayı sürdürebilir ve enzimleri de zarar görmez.'),
  ('Bir fibroblast hücresi yüzey üzerinde sürünerek ilerlerken ön ucunda yassı, yelpaze biçimli bir çıkıntı oluşturur. Bu çıkıntının ileri doğru uzamasını sağlayan olay hangisidir?', 'Ön uçta aktin ipliklerinin hızla uzaması', ['Mikrotübüllerin sentrozomda sökülmesi', 'Kontraktil kofulun boşalması', 'Kamçının dönmesi'], 'Sürünen hücrelerde ön kenardaki aktin ağı sürekli uzayarak zarı ileri iter; hücre zemine integrinlerle tutunup arka ucunu miyozin yardımıyla toplar.'),
  ('Listeria adlı bakteri konak hücrenin sitoplazmasına girdikten sonra bir ucunda konağın aktin ipliklerini hızla kurdurarak "kuyruklu yıldız" benzeri bir iz oluşturur. Bakteri bu düzenekten nasıl yararlanır?', 'Hücre içinde ilerleyip komşu hücrelere geçer', ['Konak hücrenin DNA\'sını kopyalar', 'Konağın mitokondrilerine dönüşür', 'Konak hücrenin zarını kalınlaştırır'], 'Bakterinin arkasında biriken aktin bakteriyi ileri iter; bu sayede bakteri hücre dışına çıkmadan komşu hücrelere geçerek bağışıklık sisteminden kaçar.'),
  ('Hücre iskeletinin elemanlarının mekanik görevleri karşılaştırıldığında, sıkıştırmaya (basınca) karşı direnç sağlayan eleman hangisidir?', 'Mikrotübüller', ['Ara filamentler', 'Aktin mikrofilamentleri', 'Laminler'], 'Mikrotübüller içi boş sert borular olduğundan basınca dayanır; mikrofilamentler ve ara filamentler ise daha çok çekme kuvvetlerine karşı koyar.'),
  ('Bir hücre zemine tutunduğu yerlerde, zardaki integrinlerin bir uçtan matrikse, diğer uçtan aktin demetlerine bağlandığı noktalar oluşturur. Bu yapıların hücre için önemi nedir?', 'Zemine tutunma ve hareket', ['Hücre içinde ATP üretilmesi', 'Hücrenin DNA\'sının eşlenmesi', 'Hücrenin su kaybetmesinin önlenmesi ve zarın sertleşmesi'], 'Bu odak yapışma noktaları hücre iskeleti ile matriks arasında köprüdür; hücre bu noktalardan zemini tutarak kendini ileri çeker ve çevresinden mekanik bilgi alır.'),
  ('Eklem sıvısına kaygan ve yapışkan kıvam veren, hücre dışı matrikste de bulunan uzun, dallanmamış polisakkarit hangisidir?', 'Hiyalüronik asit', ['Selüloz', 'Glikojen', 'Kitin'], 'Hiyalüronik asit çok büyük miktarda suyu bağlayan bir polisakkarittir; eklem sıvısında kayganlık, matrikste ise basınca dayanıklılık sağlar.'),
  ('Epitel dokunun altında yer alan ve epitel hücrelerini alttaki bağ dokusundan ayıran ince, yaprak biçimli hücre dışı matriks tabakasına ne ad verilir?', 'Bazal lamina', ['Orta lamel', 'Tonoplast', 'Glikokaliks'], 'Bazal lamina başlıca tip IV kollajen ve laminin proteinlerinden oluşur; epitele destek olur ve hücrelerin tutunmasını sağlar.'),
  ('Kollajen yapısındaki bozukluklardan kaynaklanan bazı kalıtsal hastalıklarda eklemlerin aşırı esnek, derinin kolay yırtılabilir olması hangi bilgiyle uyumludur?', 'Kollajenin dokulara gerilme dayanıklılığı sağlaması', ['Kollajenin hücrelerde enerji üretmesi', 'Kollajenin sinir iletimini sağlaması', 'Kollajenin kanın oksijen taşımasını sağlaması'], 'Kollajen lifleri dokuları gerilmeye karşı sağlam tutar; yapıları bozulunca bağ dokusu gevşer, eklemler aşırı hareketli, deri kırılgan olur.'),
  ('Beyin kılcal damarlarının iç yüzeyindeki hücreler arasındaki çok sıkı bağlantılar, birçok ilacın beyne geçmesini zorlaştırır. Bu engeli aşmak için ilaç tasarımında genellikle hangi özellik aranır?', 'Küçük ve yağda çözünür olma', ['Büyük ve çok yüklü olma', 'Suda hiç çözünmeme ve çok büyük olma', 'Hücre duvarına bağlanabilme'], 'Sıkı bağlantılar hücreler arası geçişi kapattığı için maddeler hücrelerin içinden, yani zarlardan geçmek zorundadır. Küçük ve yağda çözünen moleküller bunu kolaylıkla yapabilir.'),
  ('Grip virüsünün hücreye girişinin ilk adımı, virüs yüzeyindeki bir proteinin solunum yolu hücrelerinin yüzeyindeki belirli şeker uçlarına bağlanmasıdır. Bu durum glikokaliksin hangi yönünü gösterir?', 'Tanıma şekerlerinin patojenlerce kullanılması', ['Glikokaliksin virüslerin hücreye tutunmasını her zaman engellemesi', 'Glikokaliksin yalnız bitkilerde bulunması', 'Virüslerin hücre duvarına bağlanması'], 'Hücre yüzeyindeki karbonhidratlar normalde tanıma işlevi görür; ancak birçok virüs ve bakteri hedef hücreyi bu şeker işaretleri üzerinden tanır ve tutunur.'),
  ('Bölmeli mantar hiflerinde hücreleri ayıran bölme duvarlarında açıklıklar bulunur. Bu açıklıkların işlevi nedir?', 'Sitoplazma ve organellerin hif boyunca akabilmesi', ['Hiflerin fotosentez yapabilmesi', 'Sporların bu açıklıklardan saçılması', 'Hiflerin suya karşı geçirimsiz olması'], 'Bölmelerdeki gözenekler sayesinde sitoplazma, besinler ve hatta çekirdekler hif boyunca hareket edebilir; böylece misel bütün bir yapı gibi çalışır.'),
  ('Bazı mantarların hifleri bölme duvarı taşımaz ve tek bir sitoplazma içinde çok sayıda çekirdek bulundurur. Bu tür bir yapıya ne ad verilir?', 'Senositik hif', ['Bölmeli hif', 'Spor kesesi', 'Protoplast'], 'Bölmesiz hiflerde çekirdekler bölünür ama sitoplazma bölünmez; ortaya ortak sitoplazmalı, çok çekirdekli uzun bir yapı çıkar.'),
  ('Deride melanin pigmentinin yapıldığı ve sonra çevredeki epidermis hücrelerine aktarılan zarla çevrili organeller hangileridir?', 'Melanozomlar', ['Peroksizomlar', 'Glioksizomlar', 'Ribozomlar'], 'Melanozomlar lizozoma akraba, zarla çevrili organellerdir; melanositlerde melanin üretilip uzantılar aracılığıyla çevredeki keratinositlere verilir.'),
  ('Hücre içindeki lipit damlaları diğer organellerden hangi yapısal özelliğiyle ayrılır?', 'Tek katlı fosfolipitle çevrilidir', ['Çift zarlıdır ve DNA taşır', 'Hiç lipit içermez', 'Hücre duvarıyla sarılıdır'], 'Damlanın içi tamamen apolar yağdır; bu yüzden fosfolipitlerin yalnız su seven başları dışa bakacak biçimde tek bir katman yeterlidir.'),
  ('1951\'de bir hastanın rahim ağzı tümöründen alınıp laboratuvarda sınırsız bölünebilen ilk insan hücre hattı olarak bilinen ve hücre biyolojisi araştırmalarında hâlâ kullanılan hücrelere ne ad verilir?', 'HeLa hücreleri', ['Kök hücreler', 'Hayalet hücreler', 'Schwann hücreleri'], 'HeLa hücreleri, Henrietta Lacks\'tan izni alınmadan elde edilmiştir; çocuk felci aşısından kanser araştırmalarına kadar pek çok çalışmada kullanılmış, biyoetik tartışmalara da konu olmuştur.'),
  ('Wilson hastalığında bakırı hücreden dışarı ve salgı yollarına taşıyan ATP harcayan bir pompa bozuktur. Bu hastalarda ne beklenir?', 'Bakırın karaciğer ve beyinde birikmesi', ['Kanda bakırın hiç bulunmaması', 'Bakırın kemiklerde birikip kemikleri güçlendirmesi', 'Bakırın idrarla tamamen atılması'], 'Karaciğer fazla bakırı safraya pompalayarak atar. Pompa bozuk olunca bakır karaciğerde, zamanla beyin ve gözde birikir ve doku hasarına yol açar.'),
  ('Sıtma etkeni Plasmodium\'un hücrelerinde, fotosentez yapmayan ama yağ asidi gibi maddelerin sentezinde görev alan kalıntı bir plastit (apikoplast) bulunur. Bu organelin ilaç hedefi olarak önemli olmasının nedeni nedir?', 'İnsan hücrelerinde benzeri bulunmaması', ['İnsan hücrelerinde en bol bulunan organel olması', 'Parazitin çekirdeği olması', 'İnsan mitokondrileriyle aynı olması'], 'Apikoplast bakteri kökenli bir organel olduğundan, onu hedef alan ilaçlar insan hücrelerine görece az zarar verirken paraziti öldürebilir.'),
  ('Bazı deniz salyangozları yedikleri alglerin kloroplastlarını sindirmeden kendi hücrelerinde aylarca işler durumda tutabilir. Bu olaydan çıkarılabilecek en uygun sonuç hangisidir?', 'Kloroplastın yabancı hücrede çalışabildiği', ['Salyangozların kendi kloroplastlarını ürettiği', 'Kloroplastların hayvan hücrelerinde hemen sindirildiği', 'Salyangozların bitkiler âlemine dahil edilmesi gerektiği'], 'Bu olayda (kleptoplasti) kloroplastlar yabancı bir hücrede de bir süre fotosentez yapabilir; bu, endosimbiyoz sürecinin ilk evrelerini anlamak için de ilginç bir modeldir.'),
  ('Bir dokudan alınan hücreler farklı derişimdeki tuz çözeltilerine konuyor; 0,25 M\'de hücrelerin %10\'u, 0,30 M\'de %50\'si, 0,35 M\'de %90\'ı plazmoliz gösteriyor. Hücre özsuyunun osmotik derişimi için en iyi tahmin hangisidir?', 'Yaklaşık 0,30 M\'ye eşdeğer', ['0,25 M\'den düşük', '0,35 M\'den yüksek', 'Belirlenemez, çünkü hiçbir hücre plazmoliz göstermedi'], 'Hücrelerin yarısının plazmoliz gösterdiği derişim, ortalama hücre özsuyuyla izotonik kabul edilir (sınır plazmolizi); burada bu değer 0,30 M\'dir.'),
  ('Mikroenjeksiyon deneylerinde ince cam iğne hücreden çekildikten sonra hücre zarındaki deliğin kendiliğinden kapanmasının nedeni nedir?', 'Lipitlerin kendiliğinden yeniden düzenlenmesi', ['Hücre duvarının deliği hemen örtmesi', 'Ribozomların deliğin kenarlarında hızla yeni zar sentezleyip boşluğu doldurması', 'Mitokondrilerin deliği tıkaması'], 'Lipit çift katmanında açık bir kenar su sevmeyen kuyrukları suya maruz bırakır; bu enerji bakımından elverişsiz olduğundan lipitler kendiliğinden kayarak boşluğu kapatır.'),
  ('Bağırsak hücrelerine bir amino asidin alınması, ortama Na⁺/K⁺ pompasını engelleyen ouabain eklendiğinde belirgin biçimde azalıyor. Bu sonuçtan amino asidin alınma biçimi hakkında hangi çıkarım yapılabilir?', 'Na⁺ farkına bağlı olarak alındığı', ['Basit difüzyonla alındığı', 'Fagositozla alındığı', 'Ouabainin bağırsakta amino asidi parçalayarak yok ettiği'], 'Ouabain amino asit taşıyıcısını değil Na⁺/K⁺ pompasını hedef alır. Alımın azalması taşımanın pompanın kurduğu Na⁺ farkına bağımlı olduğunu gösterir.'),
  ('Oksijenin suda difüzyonu havadakinden yaklaşık on bin kat daha yavaştır. Bu bilgi suda yaşayan küçük canlılar ve hücreler için hangi sonucu doğurur?', 'Yüzeye çok yakın olmayı gerektirir', ['Sudaki canlıların hiç oksijene ihtiyacı olmaz', 'Oksijen suda havadakinden daha hızlı yayılır', 'Sudaki canlılar yalnız difüzyonla büyük boyutlara ulaşır'], 'Difüzyon suda çok yavaş olduğundan hücrelerin ve küçük su canlılarının dokuları gaz alışverişi yüzeyine çok yakın olmalıdır; daha büyük canlılarda taşıma sistemleri gerekir.'),
  ('Hücre zarı ile ER zarı kolesterol içeriği bakımından karşılaştırıldığında hangisi doğrudur?', 'Hücre zarı kolesterolce çok daha zengindir', ['ER zarı kolesterolce çok daha zengindir', 'İkisinde de hiç kolesterol yoktur', 'Kolesterol yalnız mitokondri zarında bulunur'], 'Kolesterol ER\'de yapılmasına karşın büyük kısmı hücre zarına taşınır; bu yüzden hücre zarı kolesterolce zengin, ER zarı ise görece yoksuldur.'),
  ('Bazı bakterilerde ATP sentaz, ATP üretmek yerine ATP\'yi parçalayarak zar boyunca proton pompalayabilir. Bu durum ATP sentaz hakkında neyi gösterir?', 'Tersinir çalışabildiğini', ['Yalnız ışıkla çalıştığını', 'Hiç proton taşımadığını', 'Yalnızca ökaryot hücrelerin mitokondrilerinde bulunduğunu'], 'ATP sentaz proton akışını ATP sentezine bağlar; koşullar tersine dönünce ATP\'nin enerjisini kullanarak protonları dışarı pompalayabilir. Bu, enzimin döner bir motor gibi iki yönde çalışabildiğini gösterir.'),
  ('Verem etkeni Mycobacterium tuberculosis makrofajlar tarafından yutulduğu hâlde bu hücrelerin içinde yaşamayı sürdürebilir. Bakterinin kullandığı başlıca strateji hangisidir?', 'Fagozomun lizozomla kaynaşmasını engellemek', ['Makrofajın çekirdeğine girip DNA\'sını kopyalamak', 'Makrofajın mitokondrilerine dönüşmek', 'Makrofajı fotosentez yapmaya zorlamak'], 'Bakteri içinde bulunduğu fagozomun olgunlaşıp lizozomla birleşmesini ve asitleşmesini engeller; böylece sindirilmekten kurtularak hücre içinde çoğalır.'),
  ('Lizozomda sindirilen proteinlerden açığa çıkan amino asitler hücre tarafından nasıl yeniden kullanılır?', 'Zar taşıyıcılarıyla sitoplazmaya geçerek', ['Lizozomun içinde yeniden proteine dönüşerek', 'Ekzositozla hücre dışına atılıp sonra geri alınarak', 'Doğrudan çekirdeğe akarak'], 'Lizozom zarında sindirim ürünlerini sitoplazmaya taşıyan özel taşıyıcılar bulunur; bu ürünler yeni moleküllerin yapımında kullanılır.'),
  ('Sistinozis hastalığında lizozomda proteinlerin yıkımı sırasında açığa çıkan sistin amino asidi lizozomdan çıkamaz ve kristaller oluşturur. Bu hastalıkta bozuk olan nedir?', 'Lizozom zarındaki sistin taşıyıcısı', ['Lizozomun proteaz enzimleri', 'Lizozom zarındaki proton pompası', 'Golgi\'deki işaretleme enzimi'], 'Sistinoziste enzimler çalışır ve protein yıkılır; ancak oluşan sistini dışarı taşıyan zar proteini bozuk olduğu için madde lizozomda birikir.'),
  ('Taşıma keseciklerini saran klatrin ve COP gibi kılıf proteinlerinin iki temel görevi hangisidir?', 'Keseciği biçimlendirmek ve yük seçmek', ['ATP üretmek ve DNA\'yı eşlemek', 'Keseciği sindirmek ve içindeki maddeleri yok etmek', 'Keseciği hücre duvarına yapıştırmak'], 'Kılıf proteinleri zarı kavislendirerek kesecik oluşturur; bağlandıkları adaptör proteinler aracılığıyla da keseciğe alınacak yükleri ve reseptörleri seçer.'),
  ('Bir bitki hücresinde turgor basıncı yaklaşık 0,7 MPa ölçülüyor. Bu basınç kabaca kaç atmosfere karşılık gelir? (1 atm ≈ 0,1 MPa)', 'Yaklaşık 7 atm', ['Yaklaşık 0,07 atm', 'Yaklaşık 70 atm', 'Yaklaşık 700 atm'], '0,7 MPa / 0,1 MPa = 7 atm. Bu değer bir otomobil lastiğinin iç basıncının birkaç katıdır; sağlam hücre duvarı olmadan böyle bir basınç taşınamaz.'),
  ('Niemann-Pick tip C hastalığında LDL ile hücreye alınan kolesterol lizozomdan çıkarılamaz. Bu hastalarda hücre içinde ne beklenir?', 'Kolesterolün lizozomlarda birikmesi', ['Kolesterolün hücre zarında aşırı artması', 'Lizozomların tamamen kaybolması', 'Kolesterolün çekirdekte birikmesi'], 'Kolesterolü lizozomdan dışarı taşıyan proteinler bozuk olduğundan kolesterol lizozomda kalır; hücrenin geri kalanı ise kolesterol eksikliği varmış gibi davranır.'),
  ('Hücreler ani ısı artışına maruz kaldığında bazı şaperon proteinlerinin üretiminin hızla arttığı görülür. Bu yanıtın amacı nedir?', 'Bozulan proteinleri yeniden katlamak', ['Hücre zarını kalınlaştırıp ısıyı engellemek', 'DNA\'yı ısıdan korumak için kofulda saklamak', 'Mitokondri sayısını azaltmak'], 'Isı şoku proteinleri adı verilen şaperonlar, yüksek sıcaklıkta biçimi bozulan proteinlere bağlanarak kümeleşmelerini önler ve doğru katlanmalarına yardım eder.'),
  ('Öglenanın kamçısının tabanına yakın bulunan kırmızı göz lekesi hücreye nasıl bir yarar sağlar?', 'Işığın yönünü algılamak', ['Hücrenin kontraktil kofulunu boşaltmak', 'Besinleri sindirmek', 'Hücreyi saldırganlara karşı zehirli maddelerle korumak'], 'Karotenoitçe zengin göz lekesi, kamçı tabanındaki ışığa duyarlı bölgeye düşen ışığı gölgeler; hücre bu sayede ışığın yönünü sezip fotosentez için uygun yere yüzer.'),
  ('Zayıf bir asit olan aspirin midenin çok asidik ortamında büyük ölçüde yüksüz hâlde bulunur. Bu durum aspirinin mide hücrelerine geçişini nasıl etkiler?', 'Zardan daha kolay geçer', ['Yüklü olduğu için zardan hiç geçemez', 'Yalnız fagositozla alınabilir', 'Mide asidiyle tamamen yok olur'], 'Yüksüz moleküller lipit çift katmanından kolay geçer. Asidik ortamda proton alan zayıf asitler yüksüz kaldığı için mide hücrelerine hızla girebilir.'),
  ('Aynı hacimdeki küre biçimli bir hücre ile yassı, disk biçimli bir hücre karşılaştırıldığında hangisi doğrudur?', 'Yassı hücrenin yüzey alanı daha büyüktür', ['Küre biçimli hücrenin yüzey alanı daha büyüktür', 'İkisinin yüzey alanları her zaman eşittir', 'Yassı hücrenin hacmi daha büyüktür'], 'Belirli bir hacmi en küçük yüzeyle saran biçim küredir. Yassılaşan hücrede yüzey büyür ve madde alışverişi kolaylaşır; bu nedenle gaz alışverişi yapan hücreler çoğunlukla yassıdır.'),
  ('Bir hücrede ER\'de biriken yanlış katlanmış proteinler belirli bir eşiği aştığında hücre önce protein sentezini yavaşlatıp şaperon üretimini artırır. Sorun çözülmezse hangi sonuç beklenir?', 'Apoptoza yönlendirilme', ['Hücrenin sınırsız bölünmeye başlaması', 'ER\'nin kloroplasta dönüşmesi', 'Hücre zarının tamamen kaybolması'], 'Katlanmamış protein yanıtı önce hücreyi kurtarmaya çalışır; stres sürerse hücre zarar vermemek için apoptoz yoluna girer.'),
  ('E. coli gibi kamçılı bakteriler besin kaynağına doğru düz yüzme ve rastgele dönme dönemlerini değiştirerek ilerler. Dönme hareketi kamçılarda hangi değişiklikle oluşur?', 'Kamçı motorlarının dönüş yönünün tersine çevrilmesiyle', ['Kamçıların hücreden kopmasıyla', 'Kamçıların mikrotübül eklemesiyle uzamasıyla', 'Kamçıların dinein kollarıyla bükülmesiyle'], 'Motorlar saat yönünün tersine dönerken kamçılar demet olur ve bakteri düz yüzer; yön tersine dönünce demet dağılır ve bakteri yerinde döner. Besin derişimi arttıkça dönmeler seyrekleşir.'),
  ('Hücre parçalarını santrifüjle ayırma yöntemini geliştiren ve 1974 Nobel Ödülü\'nü Palade ve de Duve ile paylaşan Belçikalı bilim insanı kimdir?', 'Albert Claude', ['Robert Hooke', 'Lynn Margulis', 'Peter Agre'], 'Albert Claude diferansiyel santrifüjü hücre biyolojisine uygulayarak organellerin ayrı ayrı incelenmesinin yolunu açmış, elektron mikroskobuyla ilk hücre görüntülerinden bazılarını da elde etmiştir.'),
  ('Bazı bitki hücrelerinde hücre duvarının içe doğru çok sayıda girinti-çıkıntı oluşturduğu ve zarın bu kıvrımları izlediği görülür. Bu "aktarım hücreleri"nin bu yapısının işlevi nedir?', 'Zar yüzeyini artırıp taşımayı hızlandırmak', ['Hücreyi mekanik olarak sertleştirip gövdeye destek sağlamak', 'Fotosentezi artırmak için ışığı yansıtmak', 'Hücrenin bölünmesini engellemek'], 'Duvar çıkıntılarını saran zar, taşıyıcı proteinler için çok daha geniş bir yüzey sağlar; bu hücreler özellikle floem yükleme bölgelerinde yoğun madde aktarımı yapar.'),
  ('İçine bakteriyi yuttuktan sonra lizozomlarla kaynaşan fagozom ile, hücrenin kendi organelini saran otofagozom arasındaki temel fark nedir?', 'Otofagozom çift zarlıdır, kendi içeriğini taşır', ['Fagozom çift zarlıdır ve hücrenin kendi organellerini taşır, otofagozom zarsızdır', 'Otofagozom lizozomla hiç kaynaşmaz', 'Fagozomun içinde DNA sentezlenir'], 'Fagozom, hücre zarının içe kıvrılmasıyla oluşan tek zarlı bir kesecikte dışarıdan alınan maddeyi taşır. Otofagozom ise sitoplazma içinde oluşan çift zarla kendi organellerini sarar.'),
  ('Bir bitki hücresinde mitokondri matriksinde üretilen bir CO₂ molekülü aynı hücredeki kloroplastın stromasına ulaşıncaya kadar kaç zardan geçer?', '4', ['2', '3', '6'], 'Mitokondrinin iç ve dış zarı ile kloroplastın dış ve iç zarı olmak üzere dört zar geçilir; molekül hücre zarından geçmez.'),
  ('Polen tüpü ve kök tüyü gibi yalnız uç kısımlarından uzayan bitki hücrelerinde büyüme nasıl gerçekleşir?', 'Uca kesecik taşınıp zar ve çeper eklenmesi', ['Hücrenin bütün yüzeyinin her yönde eşit biçimde genişlemesiyle', 'Çekirdeğin uca göç edip bölünmesiyle', 'Kloroplastların uçta yeni hücre duvarı üretmesiyle'], 'Uç büyümesinde aktin boyunca uca taşınan kesecikler ekzositozla hem zar hem duvar bileşeni ekler; böylece hücre yalnız bir yönde hızla uzar.'),
  ('Amipte sitoplazmanın dış kısmı daha katı (jel), iç kısmı ise daha akıcı (sol) kıvamdadır. Yalancı ayak oluşumunda bu iki durumun rolü nedir?', 'Sol kıvamlı iç sitoplazmanın ileri akıp uçta jelleşmesi', ['Sitoplazmanın tamamen katılaşıp hareketsiz kalması', 'Hücre zarının eriyip sitoplazmanın dışarı akması', 'Kontraktil kofulun yalancı ayağı itmesi'], 'Akıcı iç sitoplazma yalancı ayağın ucuna doğru akar ve orada aktin ağının kurulmasıyla jelleşir; arka kısımda ise jel yeniden sıvılaşır. Bu döngü hücrenin ilerlemesini sağlar.'),
  ('Pemfigus adlı hastalıkta bağışıklık sistemi deri hücrelerini birbirine bağlayan desmozom proteinlerine karşı antikor üretir. Bu hastalarda en belirgin bulgu ne olur?', 'Hücrelerin ayrılıp kabarcık oluşması', ['Derinin tamamen su geçirmez, sert ve kalın bir tabakaya dönüşmesi', 'Deri hücrelerinin hızla çoğalıp kalınlaşması', 'Derinin renginin koyulaşması'], 'Desmozomlar epidermis hücrelerini perçin gibi bağlar; bu bağlantılar bozulunca hücreler birbirinden kopar ve araya sıvı dolarak kolay yırtılan kabarcıklar oluşur.'),
  ('Bitki hücre duvarının yapısı sıklıkla betonarmeye benzetilir. Bu benzetmede çelik çubuklara karşılık gelen bileşen hangisidir?', 'Selüloz mikrofibrilleri', ['Pektin', 'Su', 'Hücre zarı'], 'Çekmeye dayanıklı selüloz mikrofibrilleri çelik çubuklar gibi iskeleti oluşturur; hemiselüloz ve pektinden oluşan matriks ise betonun karşılığıdır ve lifleri bir arada tutar.'),
  ('Bitki hücre duvarında selüloz mikrofibrillerinin yüzeyine bağlanarak onları birbirine çapraz bağlayan polisakkaritlere genel olarak ne ad verilir?', 'Hemiselülozlar', ['Glikojenler', 'Kitinler', 'Fosfolipitler'], 'Hemiselülozlar dallanmış polisakkaritlerdir; selüloz liflerine hidrojen bağlarıyla tutunarak bir ağ oluşturur ve duvarın sağlamlığına katkı yapar.'),
  ('Verem bakterisinin çeperinde bulunan mumsu mikolik asitlerin bakteriye kazandırdığı özellik hangisidir?', 'Kuruluğa ve kimyasallara direnç', ['Fotosentez yapabilme', 'Kamçıyla hızla yüzebilme', 'Konak hücreye kendi DNA\'sını aktarıp onu denetim altına alma'], 'Mikolik asitler çeperi çok az geçirgen ve su itici yapar; bu yüzden bakteri dış etkenlere dayanıklıdır, tedavisi uzun sürer ve özel boyama yöntemleriyle (aside dirençli boyama) gösterilir.'),
  ('Bir öğrenci "Zar potansiyeli yalnızca sinir ve kas hücrelerinde bulunur" diyor. Bu ifade için doğru değerlendirme hangisidir?', 'Yanlıştır; hemen bütün hücrelerde vardır', ['Doğrudur; diğer hücrelerin zarı hiçbir iyonu geçirmez', 'Doğrudur; bitki hücrelerinde iyon bulunmaz', 'Yanlıştır; zar potansiyeli yalnız bakterilerde bulunur'], 'İyon pompaları ve kanalları bütün hücrelerde bulunur; bu nedenle hemen her hücrede zarın içi dışına göre negatiftir. Sinir ve kas hücrelerini ayıran, bu potansiyeli hızla değiştirebilmeleridir.'),
  ('Bir sinir hücresinin gövdesinde üretilen keseciklerin yaklaşık 1 metre uzaklıktaki akson ucuna difüzyonla değil motor proteinlerle taşınmasının nedeni nedir?', 'Difüzyonun bu mesafede çok yavaş olması', ['Keseciklerin aksonda erimesi', 'Difüzyonun yalnız bitki hücrelerinde ve sıvı ortamlarda görülmesi', 'Akson içinde hiç sıvı bulunmaması'], 'Difüzyon süresi uzaklığın karesiyle arttığından, kısa mesafelerde etkili olan difüzyon metrelerce mesafede pratik olarak işe yaramaz; motor proteinler ise kesecikleri günler içinde taşır.'),
  ('Salgı yapan epitel hücrelerinde çekirdek genellikle hücrenin tabanında, Golgi ve salgı kesecikleri ise salgının verildiği uç kısımda bulunur. Bu düzenlemenin hücreye yararı nedir?', 'Salgı yolunun tek yönlü ve verimli işlemesi', ['Çekirdeğin salgıyla dışarı atılması', 'Golgi\'nin kan damarlarına yakın olması', 'Hücrenin bölünmesinin kolaylaşması'], 'Organellerin hücrede kutuplu dizilmesi ürünün ER\'den Golgi\'ye, oradan salgı yüzeyine düzenli akmasını sağlar; ürün doğru yüzeyden, örneğin bez kanalına, verilir.'),
  ('Bakterilerin uygun koşullarda ökaryot hücrelerden çok daha hızlı bölünebilmesine katkı yapan özelliklerden biri hangisidir?', 'Küçük boyut ve hızlı madde alışverişi', ['Çok sayıda zarlı organele sahip olup işleri paylaştırmaları', 'Mitoz geçirerek bölünmeleri', 'DNA\'larının çekirdek zarıyla korunması'], 'Küçük bakteriler besinleri hızla alır, atıkları hızla verir; basit yapıları ve tek halkasal kromozomları da hızlı eşlenme ve bölünmeye olanak tanır.'),
  ('Mitokondri DNA\'sının çekirdek DNA\'sına göre daha hızlı mutasyon biriktirmesinin nedenleri arasında hangisi gösterilir?', 'Histonsuz olması ve oksidatif hasara yakınlığı', ['Hiç eşlenmemesi', 'Çekirdek zarıyla çevrili olup onarım enzimlerinden uzak kalması', 'Yalnız RNA\'dan oluşması'], 'Mitokondri DNA\'sı histonsuzdur, onarım sistemleri daha sınırlıdır ve elektron taşıma zincirinde oluşan zararlı oksijen türlerinin hemen yanındadır.'),
  ('Çok eski kemik ve saç gibi bozulmuş örneklerde mitokondri DNA\'sının çekirdek DNA\'sından daha kolay elde edilebilmesinin başlıca nedeni nedir?', 'Her hücrede yüzlerce, binlerce kopya bulunması', ['Mitokondri DNA\'sının çekirdek DNA\'sından daha uzun olması', 'Mitokondri DNA\'sının hiç bozulmaması', 'Mitokondrilerin yalnız kemikte bulunması'], 'Bir hücrede tek çift çekirdek genomu varken mitokondri DNA\'sı çok sayıda kopya hâlinde bulunur; bu yüzden az ve bozulmuş örneklerde bile bir kısmı sağlam kalır.'),
  ('Hücrede belirli bir proteinin yerini göstermek için o proteine özgül olarak bağlanan ve floresan boyayla işaretlenmiş antikorların kullanıldığı yönteme ne ad verilir?', 'İmmünfloresan boyama', ['Gram boyama', 'Diferansiyel santrifüj', 'Dondurarak kırma'], 'Antikorlar hedef proteine çok seçici bağlandığından, tespit edilmiş hücrelerde proteinin hangi organelde ya da yapıda yoğunlaştığı floresan mikroskobuyla görülebilir.'),
  ('Transmisyon elektron mikroskobu için dokular elmas ya da cam bıçaklı özel bir aletle yaklaşık 50–100 nm kalınlığında kesilir. Kesitlerin bu kadar ince olmasının nedeni nedir?', 'Elektronların kalın örnekten geçememesi', ['Örneğin daha hızlı kuruması', 'Işığın örneği boyaması', 'Hücrelerin kesildikten sonra da canlı kalıp hareket etmesi'], 'Elektronlar maddeyle güçlü etkileştiğinden kalın örneklerden geçemez; görüntü oluşabilmesi için kesitlerin ışık mikroskobu kesitlerinden yüzlerce kat ince olması gerekir.'),
  ('Hücre duvarı taşımayan mikoplazmaların zarlarında konaktan aldıkları sterollerin bulunması bu bakterilere ne sağlar?', 'Duvarın yokluğunda zara ek sağlamlık ve kararlılık', ['Fotosentez yapma yeteneği', 'Kamçı oluşturma yeteneği', 'Çekirdek zarı oluşturma yeteneği'], 'Çoğu bakteri zarında sterol bulunmaz; duvarsız mikoplazmalar ise konaktan sağladıkları sterollerle zarlarını güçlendirerek osmotik ve mekanik zorlanmalara dayanır.'),
  ('Bir öğrenci "Golgi cisimciği yalnızca salgı yapan hücrelerde bulunur" diyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Yanlıştır; hemen bütün ökaryot hücrelerde bulunur', ['Doğrudur; salgı yapmayan hücrelerde hiç Golgi cisimciği bulunmaz', 'Doğrudur; Golgi yalnız bitkilerde bulunur', 'Yanlıştır; Golgi yalnız prokaryotlarda bulunur'], 'Salgı hücrelerinde Golgi daha gelişmiştir; ancak her ökaryot hücre zar proteinlerini, glikolipitleri ve lizozom enzimlerini işlemek için Golgi\'ye gereksinim duyar.'),
  ('Süngerlerin hücreleri elekten geçirilerek birbirinden ayrıldığında ve iki farklı türün hücreleri karıştırıldığında, hücrelerin bir süre sonra yalnız kendi türlerinin hücreleriyle yeniden kümelendiği görülür. Bu deney hangi hücresel özelliği gösterir?', 'Türe özgü yüzey tanıması', ['Hücrelerin yalnız büyüklüklerine göre kendiliğinden ayrışması', 'Hücrelerin yeniden kümelenmek için bölünmesi', 'Hücrelerin fotosentezle birbirini bulması'], 'Hücre yüzeyindeki yapışma molekülleri aynı türden hücreleri tanıyıp birbirine bağlar; bu deney hücre tanımanın çok hücreli yapı için temel önemini gösterir.'),
  ('Bazı epitel kökenli kanserlerde hücrelerin komşularına tutunmasını sağlayan E-kaderin proteininin azalması tümörün davranışını nasıl etkiler?', 'Hücrelerin kopup başka dokulara yayılmasını kolaylaştırır', ['Tümörün yerinde kalıp hiç büyümemesine yol açar', 'Hücrelerin daha sıkı yapışmasını sağlar', 'Tümör hücrelerinin fotosentez yapmasına yol açar'], 'Kaderin kaybıyla hücreler arası yapışma zayıflar; tümör hücreleri ana kitleden kolayca ayrılıp çevre dokulara ve damarlara girebilir.'),
  ('Bir makrofaja aktin ipliklerinin kurulmasını engelleyen sitokalasin verildiğinde bakterileri yutamadığı görülüyor. Bu sonuç fagositoz hakkında neyi gösterir?', 'Fagositozun aktine bağımlı olduğunu', ['Fagositozun yalnız mikrotübüllerle yapıldığını', 'Bakterilerin hücre içinde aktin iplikleriyle sindirildiğini', 'Fagositozun enerji gerektirmediğini'], 'Fagositozda zar, bakteriyi sarmak için aktin ipliklerinin itmesiyle uzanır; aktin kurulumu engellenince çıkıntılar oluşamaz ve yutma gerçekleşmez.'),
  ('Covid-19 salgınında geliştirilen mRNA aşılarında mRNA moleküllerinin lipit nanoparçacıklar içine yerleştirilmesinin başlıca nedeni nedir?', 'mRNA\'yı korumak ve hücreye sokmak', ['mRNA\'yı DNA\'ya dönüştürmek', 'mRNA\'nın çekirdeğe girip konak genomuna kalıcı olarak eklenmesini sağlamak', 'mRNA\'yı hücre duvarına bağlamak'], 'Büyük ve negatif yüklü mRNA zardan kendiliğinden geçemez ve kolayca yıkılır. Lipit nanoparçacıklar onu korur ve hücreye endositozla alınmasını sağlar.'),
  ('Sindirim enzimi salgılayan bir hücrede, salgı keseciklerinin hücre zarına taşınmasında hücre iskeletinin hangi elemanları yol görevi görür?', 'Mikrotübüller ve zarın hemen altında aktin iplikleri', ['Yalnız ara filamentler', 'Hücre duvarındaki selüloz lifleri', 'Çekirdek laminası'], 'Kesecikler uzun mesafede mikrotübüller boyunca motor proteinlerle taşınır; zara yakın bölgede ise aktin ağı ve miyozin motorları son aşamayı üstlenir.'),
  ('Bir hücrede ER zarına bağlı ribozomlar ile serbest ribozomların oranının, hücrenin salgı yapmaya başlamasıyla değiştiği gözleniyor. Hangi değişiklik beklenir?', 'ER\'ye bağlı ribozomların oranı artar', ['Serbest ribozomların oranı artar', 'Ribozomların tamamı çekirdeğe göç eder', 'Ribozom sayısı sıfıra iner'], 'Salgı proteinleri ER\'ye bağlı ribozomlarda sentezlenir; salgı başlayınca bu proteinleri yapan ribozomlar sinyal dizileri aracılığıyla ER\'ye bağlanır ve bağlı ribozomların payı artar.'),
  ('Bağırsak kurtlarına karşı kullanılan bazı ilaçlar parazitin tübülinine insan tübülininden çok daha güçlü bağlanır. Bu ilaçların parazite seçici etkisinin hücresel temeli nedir?', 'Parazitin mikrotübül kurulumunun bozulması', ['Parazitin hücre duvarının yıkılması', 'Parazitin kloroplastlarının çalışmaması', 'İnsan ribozomlarının durdurulması'], 'Tübüline bağlanan ilaç parazit hücrelerinde mikrotübül oluşumunu engeller; besin emilimi ve hücre bölünmesi bozulan parazit ölür. Tübülinler arasındaki küçük farklar seçiciliği sağlar.'),
  ('Tek hücreli bir canlının sitoplazmasında bulunan ve sindirim enzimleriyle kaynaşmış besin kofulu ile sindirimin bittiği artık kofulu ayırt etmek için hangi ölçüt en uygundur?', 'İçindeki besin parçacıklarının parçalanmış ve azalmış olması', ['Kofulun çift zarlı olması', 'Kofulun çekirdek taşıması', 'Kofulun klorofil içermesi'], 'Sindirim ilerledikçe kofulun içindeki besin parçacıkları küçülür ve yararlı maddeler sitoplazmaya geçer; geriye yalnız sindirilemeyen artıklar kalır.'),
  ('Hücre zarına yerleşmiş bir proteinin hücre dışına bakan kısmında şeker zincirleri, sitoplazmaya bakan kısmında ise fosfat eklenebilen amino asitler bulunuyor. Bu durumdan hangi sonuç çıkarılır?', 'İki yüzün farklı işlevler gördüğü', ['Proteinin zarda sürekli takla attığı', 'Proteinin zarda değil, yalnız sitoplazmada çözünmüş hâlde bulunduğu', 'Şekerlerin hücre içinde eklendiği'], 'Şekerler ER ve Golgi\'de lümen tarafına eklenir ve sonunda dışa bakar; fosforlama ise sitoplazmadaki enzimlerce yapılır. Bu, zar proteinlerinin kalıcı bir yönelimi olduğunu gösterir.'),
  ('Hücre zarının iki yüzünden birinde bulunan ve dış ortamdaki bir hormonu tanıyan reseptörün, zarın iç yüzüne bakan kısmında genellikle hangi tür bölge yer alır?', 'Hücre içindeki sinyal proteinleriyle etkileşen bölge', ['Hormonu ikinci kez bağlayan bölge', 'DNA\'ya bağlanan bölge', 'Hücre duvarına tutunan bölge'], 'Reseptörün dış kısmı sinyali tanır; iç kısmı ise biçim değişikliğini G proteinleri ya da kinazlar gibi hücre içi moleküllere ileterek yanıtı başlatır.'),
  ('Kloroplastta tilakoit zarlarıyla çevrili iç boşluğa ne ad verilir?', 'Tilakoit lümeni', ['Stroma', 'Matriks', 'Zarlar arası boşluk'], 'Tilakoitlerin içi lümen olarak adlandırılır; stroma ise tilakoitlerin dışında, kloroplast iç zarının çevrelediği sıvı bölmedir.'),
  ('Taramalı elektron mikroskobunda incelenecek kurutulmuş biyolojik örneklerin yüzeyinin çok ince bir altın tabakasıyla kaplanmasının amacı nedir?', 'Yüzeyi iletken yapmak', ['Örneği canlı tutmak', 'Örneğe doğal rengini kazandırıp renkli fotoğraf çekmek', 'Örneğin içini görünür kılmak'], 'Biyolojik örnekler elektriği iletmediğinden üzerlerinde yük birikir; ince metal kaplama bu yükü dağıtır ve yüzeyden saçılan elektronlarla ayrıntılı üç boyutlu görüntü elde edilir.'),
  ('Floresan mikroskopisinde kullanılan boyaların temel özelliği hangisidir?', 'Işığı soğurup daha uzun dalga boyunda yaymaları', ['Elektronları güçlü biçimde saçıp yapıları koyu göstermeleri', 'Yalnızca canlı hücrelerde çözünmeleri', 'Işığı hiç soğurmamaları'], 'Floresan madde örneğin mavi ışığı soğurup yeşil ışık yayar; mikroskop yalnız yayılan ışığı geçiren süzgeçlerle işaretli yapıları karanlık zemin üzerinde parlak gösterir.'),
];
